export default "            # tower keeps activation checkpointing too.\\n\\n        self._deepspeed_engine = None\\n        dist_name = self.args.dist_config.name if self.args.dist_config is not None else None\\n\\n        if dist_name == \\\"deepspeed\\\":\\n            if self.args.cp_size > 1:\\n                raise ValueError(\\\"Context parallelism currently requires `dist_config.name: fsdp2`.\\\")\\n\\n            from ..plugins.trainer_plugins.distributed.interface import DistributedPlugin\\n\\n            self._deepspeed_engine = DistributedPlugin(\\\"deepspeed\\\").shard_model(\\n                self.model,\\n                self.args.dist_config,\\n                num_micro_batch=self.train_batch_generator.num_micro_batch,\\n                micro_batch_size=self.args.micro_batch_size,\\n            )\\n            self._init_optimizer()\\n            self._init_lr_scheduler()\\n            self.model, self.optimizer, self.lr_scheduler = self._deepspeed_engine.prepare(\\n                self.model, self.optimizer, self.lr_scheduler\\n            )\\n        else:\\n            # fsdp2 / DDP / no dist\\n            self._shard_model()\\n            self._init_optimizer()\\n            self._init_lr_scheduler()\\n\\n        self._resume_epoch = 0\\n        self._checkpoint = TrainingCheckpointCoordinator(self)\\n        if self.args.resume_from_checkpoint:\\n            self._checkpoint.resume(self.args.resume_from_checkpoint)\\n\\n        if self.args.save_ckpt_as_hf:\\n            logger.warning_rank0(\\n                \\\"save_ckpt_as_hf is enabled. Intermediate checkpoints will be saved in Hugging Face format. \\\"\\n                \\\"Note that this will significantly increase memory consumption during saving.\\\"\\n            )\\n\\n        # Callbacks\\n        self.callback_handler = CallbackHandler([LoggingCallback()], trainer=self)\\n        for cb in callbacks or []:\\n            self.callback_handler.add_callback(cb)\\n\\n        # Callbacks: TrainerState tracks progress across the full run.\\n        self.state = TrainerState(\\n            num_training_steps=self.num_training_steps,\\n            global_step=self.global_step,\\n            epoch=self._resume_epoch,\\n        )\\n        # Keep callback state aligned with checkpoint-resumed trainer counters.\\n        self.state.global_step = self.global_step\\n        self.state.epoch = self._resume_epoch\\n\\n        if self.args.cp_size > 1:\\n            from ..plugins.model_plugins.parallelization.sequence_parallel import SequenceParallelModelPlugin\\n\\n            if model.config._attn_implementation != \\\"flash_attention_2\\\":\\n                raise ValueError(\\n                    \\\"Sequence parallelism requires flash attention. Please set `flash_attn: flash_attention_2`.\\\"\\n                )\\n\\n            SequenceParallelModelPlugin(self.args.cp_mode)(model, self.args.cp_size)\\n\\n    def _create_batch_generator(self) -> None:\\n        if (\\n            self.args.batching_strategy == BatchingStrategy.PADDING_FREE\\n            and getattr(self.model.config, \\\"_attn_implementation\\\", None) != \\\"flash_attention_2\\\"\\n        ):\\n            raise ValueError(\\\"`padding_free` requires `flash_attn: flash_attention_2`.\\\")\\n\\n        self.train_batch_generator = BatchGenerator(\\n            dataset=self.train_dataset,\\n            renderer=self.renderer,\\n            micro_batch_size=self.args.micro_batch_size,\\n            global_batch_size=self.args.global_batch_size,\\n            cutoff_len=self.args.cutoff_len,\\n            batching_workers=self.args.batching_workers,\\n            batching_strategy=self.args.batching_strategy,\\n            seed=self.args.seed,\\n        )\\n\\n    def _shard_model(self) -> None:\\n        if self.args.dist_config is None:\\n            if DistributedInterface().get_world_size(Dim.DP) > 1:\\n                from torch.nn.parallel import DistributedDataParallel as DDP\\n\\n                logger.warning_rank0(\\n                    \\\"dist_config is None but distributed training is enabled; falling back to DistributedDataParallel.\\\"\\n                )\\n                device_ids = None if self.device.type == \\\"cpu\\\" else [self.device.index]\\n                # Multimodal models invoke the vision tower only when a step carries media; a\\n                # globally media-less step leaves vision params unused, which trips DDP's default\\n                # all-params-used assertion. (FSDP tolerates a uniform skip; DDP does not.)\\n                find_unused = not is_tokenizer(self.renderer.processor)\\n                self.model = DDP(self.model, device_ids=device_ids, find_unused_parameters=find_unused)\\n        else:\\n            from ..plugins.trainer_plugins.distributed.interface import DistributedPlugin\\n\\n            self.model = DistributedPlugin(self.args.dist_config.name).shard_model(\\n                self.model,\\n                self.args.dist_config,\\n                bf16=self.args.bf16,\\n            )\\n\\n    def _init_optimizer(self) -> None:\\n        \\\"\\\"\\\"Init optimizer.\\\"\\\"\\\"\\n        if self.args.optim_config is None:\\n            _trainable_params = [p for p in self.model.parameters() if p.requires_grad]\\n            self.optimizer = torch.optim.AdamW(_trainable_params, lr=self.args.learning_rate)\\n        else:\\n            from ..plugins.trainer_plugins.optimizers.optimizer import OptimizerPlugin\\n\\n            self.optimizer = OptimizerPlugin(self.args.optim_config.name)(self.model, self.args.optim_config)\\n\\n    def _init_lr_scheduler(self) -> None:\\n        \\\"\\\"\\\"Init lr scheduler.\\\"\\\"\\\"\\n        if self.args.lr_scheduler_config is None:\\n            self.lr_scheduler = torch.optim.lr_scheduler.LambdaLR(self.optimizer, lr_lambda=lambda x: 1.0)\\n        else:\\n            from ..plugins.trainer_plugins.lr_scheduler import LRSchedulerPlugin\\n\\n            self.lr_scheduler = LRSchedulerPlugin(self.args.lr_scheduler_config.name)(\\n                self.optimizer, self.num_training_steps, self.args.lr_scheduler_config\\n            )\\n\\n    def compute_log_probs(self, model: HFModel, batch: BatchInput) -> Tensor:\\n        \\\"\\\"\\\"Compute log probs.\\n\\n        log_probs: Tensor of shape (batch_size, seq_len - 1)\\n        \\\"\\\"\\\"\\n        batch_size, _ = batch[\\\"labels\\\"].shape\\n        model_inputs = {\\n            k: v.to(self.device, non_blocking=True) for k, v in batch.items() if isinstance(v, torch.Tensor)\\n        }\\n        # Let mRoPE models build their own multimodal 3D position ids (see _uses_mrope in __init__).\\n        if self._uses_mrope:\\n            model_inputs.pop(\\\"position_ids\\\", None)\\n        labels = batch[\\\"labels\\\"].to(self.device, non_blocking=True)\\n        outputs: ModelOutput = model(**model_inputs)\\n        logits = outputs.logits.float()\\n        shift_labels = labels[..., 1:].contiguous().view(-1)\\n        shift_logits = logits[..., :-1, :].contiguous().view(shift_labels.size(0), -1)\\n        return -F.cross_entropy(shift_logits, shift_labels, reduction=\\\"none\\\").view(batch_size, -1)\\n\\n    @abstractmethod\\n    def compute_loss(self, batch: BatchInput) -> Tensor:\\n        \\\"\\\"\\\"Compute the scalar loss.\\n\\n        Subclasses must handle sequence-parallel layout and loss aggregation when\\n        `self.cp_size > 1`, or reject context parallelism during initialization.\\n        The shared training loop does not dispatch sequence-parallel loss.\\n        \\\"\\\"\\\"\\n        ...\\n\\n    def fit(self) -> None:\\n        \\\"\\\"\\\"Train the model.\\\"\\\"\\\"\\n        self.model.train()\\n        self.callback_handler.on_train_begin(self.args, self.state)\\n\\n        epoch = self._resume_epoch\\n        while self.global_step < self.num_training_steps:\\n            self.state.epoch = epoch\\n            self.train_batch_generator.set_epoch(epoch)\\n            self.callback_handler.on_epoch_begin(self.args, self.state)\\n\\n            # BatchGenerator is an iterator; each loop step calls its __next__ to produce one optimizer step.\\n            for micro_batches in self.train_batch_generator:\\n                self.global_step += 1\\n\\n                self.state.global_step = self.global_step\\n                self.callback_handler.on_step_begin(self.args, self.state)\\n\\n                step_loss = 0\\n                step_valid_tokens = compute_valid_tokens(micro_batches)\\n                step_valid_tokens = DistributedInterface().all_reduce(step_valid_tokens, op=ReduceOp.SUM)\\n                num_micro = len(micro_batches)\\n                for i, micro_batch in enumerate(micro_batches):\\n                    loss = self.compute_loss(micro_batch)\\n                    mini_step_valid_tokens = compute_valid_tokens([micro_batch])\\n                    # fsdp uses mean reduction so we need to scale the loss by dp_size\\n                    loss = loss * mini_step_valid_tokens * self.dp_size / (step_valid_tokens + 1e-6)\\n\\n                    if self._deepspeed_engine is not None:\\n                        # deepspeed: set sync_gradients so engine.step() only fires on last micro-batch\\n                        self._deepspeed_engine.accelerator.sync_gradients = i == num_micro - 1\\n                        self._deepspeed_engine.backward(loss)\\n                    else:\\n                        loss.backward()\\n                    step_loss += loss.item()\\n\\n                if self._deepspeed_engine is not None:\\n                    # deepspeed: engine.step() already ran inside backward at the sync boundary\\n                    grad_norm = self._deepspeed_engine.get_grad_norm()\\n                else:\\n                    dist_name = self.args.dist_config.name if self.args.dist_config else None\\n                    if dist_name == \\\"fsdpturbo\\\":\\n                        from ..plugins.trainer_plugins.distributed.interface import DistributedPlugin\\n\\n                        grad_norm = DistributedPlugin(dist_name).clip_grad_norm(self.model, self.args.max_grad_norm)\\n                    else:\\n                        # FSDP2 shards params/grads across the fsdp mesh, so clip_grad_norm_ returns a\\n                        # per-rank local shard norm. Materialize the true global norm before clipping.\\n                        grads = [p.grad for p in self.model.parameters() if p.grad is not None]\\n                        total_norm = torch.nn.utils.get_total_norm(grads)\\n                        if isinstance(total_norm, DTensor):\\n                            # full_tensor all-reduces across the fsdp mesh (spans CP under default\\n                            # mp_shard=world); a separate CP reduce would over-count by sqrt(cp_size).\\n                            total_norm = total_norm.full_tensor()\\n                        torch.nn.utils.clip_grads_with_norm_(\\n                            self.model.parameters(), self.args.max_grad_norm, total_norm\\n                        )\\n                        grad_norm = total_norm.item()\\n                        # Do not retain a full generation of gradient tensors across optimizer\\n                        # steps. ``zero_grad(set_to_none=True)`` clears ``param.grad``, but this\\n                        # local list would otherwise keep every old gradient alive until the next\\n                        # assignment, doubling gradient memory during the following backward.\\n                        del grads\\n\\n                    if not torch.isfinite(torch.tensor(grad_norm)):  # type: ignore # pyright: ignore [reportUnknownReturnType]\\n                        logger.warning_rank0(f\\\"Gradient norm is not finite: {grad_norm}\\\")\\n                    else:\\n                        self.optimizer.step()\\n\\n                    self.lr_scheduler.step()\\n                    self.optimizer.zero_grad()\\n\\n                step_loss, grad_norm = DistributedInterface().all_reduce([step_loss, grad_norm])\\n                DistributedInterface().sync()\\n\\n                # Update state with step metrics\\n                current_lr = (\\n                    self.lr_scheduler.get_last_lr()[0]\\n                    if hasattr(self.lr_scheduler, \\\"get_last_lr\\\")\\n                    else self.args.learning_rate\\n                )\\n                self.state.loss = step_loss\\n                self.state.grad_norm = grad_norm\\n                self.state.learning_rate = current_lr\\n\\n                self.callback_handler.on_step_end(self.args, self.state)\\n\\n                # Logging: trainer decides when to log\\n                if self.global_step % self.args.logging_steps == 0:\\n                    logs = {\\n                        \\\"epoch\\\": epoch,\\n                        \\\"step\\\": self.state.global_step,\\n                        \\\"loss\\\": step_loss,\\n                        \\\"grad_norm\\\": grad_norm,\\n                        \\\"learning_rate\\\": current_lr,\\n                    }\\n                    # Merge per-step trainer metrics (e.g. DPO rewards/logps/logits)\\n                    step_metrics = getattr(self, \\\"_step_metrics\\\", None)\\n                    if step_metrics:\\n                        logs.update(step_metrics)\\n                    self.callback_handler.on_log(self.args, self.state, logs)\\n\\n                if self.args.save_steps and self.global_step % self.args.save_steps == 0:\\n                    self._checkpoint.save(epoch)\\n\\n                # Check if max_steps is reached\\n                if self.global_step >= self.num_training_steps:\\n                    logger.info_rank0(f\\\"Reached max_steps ({self.num_training_steps}), stopping training.\\\")\\n                    self.callback_handler.on_epoch_end(self.args, self.state)\\n                    self.callback_handler.on_train_end(self.args, self.state)\\n                    return\\n\\n            self.callback_handler.on_epoch_end(self.args, self.state)\\n            epoch += 1\\n\\n        self.callback_handler.on_train_end(self.args, self.state)\\n\\n    def save_model(self) -> None:\\n        \\\"\\\"\\\"Save the model.\\\"\\\"\\\"\\n        if self.args.dist_config is not None and self.args.dist_config.name in (\\\"deepspeed\\\", \\\"fsdp2\\\", \\\"fsdpturbo\\\"):\\n            from ..plugins.trainer_plugins.distributed.interface import DistributedPlugin\\n\\n            DistributedPlugin(self.args.dist_config.name).save_model(\\n                self.model, self.args.output_dir, self.renderer.processor\\n            )\\n        else:\\n            model_to_save = self.model.module if hasattr(self.model, \\\"module\\\") else self.model\\n            model_to_save.save_pretrained(\\n                self.args.output_dir, state_dict=model_to_save.state_dict(), max_shard_size=\\\"4GB\\\"\\n            )\\n            self.renderer.processor.save_pretrained(self.args.output_dir, max_shard_size=\\\"4GB\\\")\\n            logger.info_rank0(f\\\"Model saved to {self.args.output_dir}\\\")\\n\\n        self.callback_handler.on_save(self.args, self.state)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/data_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9e1de9035a7f9eb7a61b4fe3c179694a49a7ddce29a6ff899f9e4935acdeefeb\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"The definition of data engine.\\n\\nHow to use:\\ndata_engine = DataEngine(data_args.train_dataset)\\ndata_engine[i]: Get the sample via index.\\n\\nInit workflow:\\n1. Parse dataset info from arguments.\\n2. Load datasets according to dataset info.\\n3. Build data index (and reweight samples if necessary).\\n\\nGet data sample:\\n1. Get sample from data index.\\n2. Convert sample to standard format.\\n3. Return sample.\\n\\nNote:\\n1. The data engine is equivalent to the torch dataset.\\n2. The data engine is agnostic to the model used.\\n\\\"\\\"\\\"\\n\\nimport os\\nfrom collections.abc import Iterable\\nfrom typing import Any\\n\\nfrom huggingface_hub import hf_hub_download\\nfrom omegaconf import OmegaConf\\nfrom torch.utils.data import Dataset\\n\\nfrom ..utils.types import DatasetInfo, HFDataset, Sample\\n\\n\\nclass DataEngine(Dataset):\\n    \\\"\\\"\\\"Data engine.\\n\\n    Args:\\n        data_args: Data arguments.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, dataset_path: str) -> None:\\n        self.path = dataset_path\\n        \\\"\\\"\\\"Dataset path.\\\"\\\"\\\"\\n        self.datasets: dict[str, HFDataset] = {}\\n        \\\"\\\"\\\"Dict of (dataset_name, dataset)\\\"\\\"\\\"\\n        self.dataset_infos: dict[str, DatasetInfo] = {}\\n        \\\"\\\"\\\"Dict of (dataset_name, dataset_info)\\\"\\\"\\\"\\n        self.data_index: list[tuple[str, int, int | None]] = []\\n        \\\"\\\"\\\"List of (dataset_name, sample_index, cut). ``cut`` is the prefix length for multi-turn\\n        split (messages[:cut], ending at one supervised assistant turn), or None for a whole sample.\\\"\\\"\\\"\\n        self.streaming: bool = False\\n        \\\"\\\"\\\"Whether dataset is streaming.\\\"\\\"\\\"\\n        self._get_dataset_info()\\n        self._load_dataset()\\n        self._build_data_index()\\n\\n    def _get_dataset_info(self) -> None:\\n        \\\"\\\"\\\"Get dataset info from data arguments.\\\"\\\"\\\"\\n        if self.path.endswith(\\\".yaml\\\") and os.path.isfile(self.path):  # local file\\n            self.dataset_infos = OmegaConf.load(self.path)\\n        elif self.path.endswith(\\\".yaml\\\"):  # hf hub uri, e.g. llamafactory/v1-sft-demo/dataset_info.yaml\\n            repo_id, filename = os.path.split(self.path)\\n            filepath = hf_hub_download(repo_id=repo_id, filename=filename, repo_type=\\\"dataset\\\")\\n            self.dataset_infos = OmegaConf.load(filepath)\\n        elif os.path.exists(self.path):  # local file(s)\\n            self.dataset_infos = {\\\"default\\\": {\\\"path\\\": self.path, \\\"source\\\": \\\"local\\\"}}\\n        else:  # hf hub dataset, e.g. llamafactory/v1-sft-demo\\n            self.dataset_infos = {\\\"default\\\": {\\\"path\\\": self.path}}\\n\\n    def _load_dataset(self) -> None:\\n        \\\"\\\"\\\"Load datasets according to dataset info.\\\"\\\"\\\"\\n        is_streaming = [dataset_info.get(\\\"streaming\\\", False) for dataset_info in self.dataset_infos.values()]\\n        self.streaming = any(is_streaming)\\n        if all(is_streaming) != any(is_streaming):\\n            raise ValueError(\\\"All datasets must be streaming or non-streaming.\\\")\\n\\n        for dataset_name, dataset_info in self.dataset_infos.items():\\n            split = dataset_info.get(\\\"split\\\", \\\"train\\\")\\n            if dataset_info.get(\\\"source\\\", \\\"hf_hub\\\") == \\\"hf_hub\\\":\\n                from datasets import load_dataset\\n\\n                self.datasets[dataset_name] = load_dataset(dataset_info[\\\"path\\\"], split=split, streaming=self.streaming)\\n            else:  # data loader plugin\\n                from ..plugins.data_plugins.loader import DataLoaderPlugin\\n\\n                self.datasets[dataset_name] = DataLoaderPlugin(dataset_info[\\\"source\\\"]).load(dataset_info)\\n\\n    def _build_data_index(self) -> None:\\n        \\\"\\\"\\\"Build dataset index.\\n\\n        Multi-turn SFT conversations are prefix-expanded: one index entry per supervised assistant\\n        turn, so ``len()`` reflects the true number of training samples (each trained on its last\\n        turn). Entries are ``(dataset_name, sample_index, cut)``; ``cut`` is the prefix length\\n        ``messages[:cut]`` ending at one supervised turn, or ``None`` for a whole sample (DPO,\\n        streaming, or no supervised turn).\\n        \\\"\\\"\\\"\\n        for dataset_name, dataset in self.datasets.items():\\n            if self.streaming:  # cannot pre-count turns -> keep whole, unsplit\\n                data_index = [(dataset_name, -1, None) for _ in range(1000)]\\n            else:\\n                data_index = []\\n                for sample_index in range(len(dataset)):\\n                    sample = self._convert_data_sample(dataset[sample_index], dataset_name)\\n                    for cut in self._prefix_cuts(sample):\\n                        data_index.append((dataset_name, sample_index, cut))\\n\\n            size = self.dataset_infos[dataset_name].get(\\\"size\\\")\\n            weight = self.dataset_infos[dataset_name].get(\\\"weight\\\")\\n            if size or weight:\\n                from ..plugins.data_plugins.loader import adjust_data_index\\n\\n                data_index = adjust_data_index(data_index, size, weight)\\n\\n            self.data_index.extend(data_index)\\n\\n    @staticmethod\\n    def _prefix_cuts(sample: Sample) -> list[int | None]:\\n        \\\"\\\"\\\"Prefix lengths to split a multi-turn conversation on: one per supervised assistant turn.\\n\\n        ``u1 a1 u2 a2`` -> ``[2, 4]`` (samples ``messages[:2]`` and ``messages[:4]``, each trained on\\n        its last assistant turn). Non-SFT samples (no ``messages``) or those with no supervised turn\\n        are kept whole (``[None]``).\\n        \\\"\\\"\\\"\\n        messages = sample.get(\\\"messages\\\")\\n        if not messages:\\n            return [None]\\n        cuts = [i + 1 for i, m in enumerate(messages) if m[\\\"role\\\"] == \\\"assistant\\\" and m.get(\\\"loss_weight\\\", 1.0) > 1e-6]\\n        return cuts or [None]\\n\\n    def _convert_data_sample(self, raw_sample: dict[str, Any], dataset_name: str) -> Sample:\\n        \\\"\\\"\\\"Convert dataset sample.\\n\\n        Args:\\n            raw_sample (dict[str, Any]): Raw dataset sample.\\n            dataset_name (str): Dataset name.\\n\\n        Returns:\\n            Sample: Dataset sample.\\n        \\\"\\\"\\\"\\n        converter = self.dataset_infos[dataset_name].get(\\\"converter\\\")\\n        if converter is not None:\\n            from ..plugins.data_plugins.converter import DataConverterPlugin\\n\\n            return {\\\"_dataset_name\\\": dataset_name, **DataConverterPlugin(converter)(raw_sample)}\\n        else:\\n            return {\\\"_dataset_name\\\": dataset_name, **raw_sample}\\n\\n    def __len__(self) -> int:\\n        \\\"\\\"\\\"Get dataset length.\\n\\n        Returns:\\n            int: Dataset length.\\n        \\\"\\\"\\\"\\n        if self.streaming:\\n            return -1\\n        else:\\n            return len(self.data_index)\\n\\n    def __getitem__(self, index: int | Any) -> Sample | list[Sample]:\\n        \\\"\\\"\\\"Get dataset item.\\n\\n        Args:\\n            index (int): Dataset index.\\n\\n        Returns:\\n            Sample: Dataset item.\\n        \\\"\\\"\\\"\\n        if self.streaming:\\n            raise ValueError(\\\"Streaming dataset does not support index access.\\\")\\n\\n        if isinstance(index, int):\\n            return self._get(*self.data_index[index])\\n        else:  # data selector plugin\\n            from ..plugins.data_plugins.loader import select_data_sample\\n\\n            selected_index = select_data_sample(self.data_index, index)\\n            if isinstance(selected_index, list):\\n                return [self._get(*entry) for entry in selected_index]\\n            else:\\n                return self._get(*selected_index)\\n\\n    def _get(self, dataset_name: str, sample_index: int, cut: int | None = None) -> Sample:\\n        \\\"\\\"\\\"Convert one raw row, truncating to a multi-turn prefix when ``cut`` is set.\\\"\\\"\\\"\\n        sample = self._convert_data_sample(self.datasets[dataset_name][sample_index], dataset_name)\\n        if cut is not None and \\\"messages\\\" in sample:\\n            sample = {**sample, \\\"messages\\\": sample[\\\"messages\\\"][:cut]}\\n        return sample\\n\\n    def __iter__(self) -> Iterable[Sample]:\\n        \\\"\\\"\\\"Get dataset iterator.\\n\\n        Returns:\\n            Iterable[Sample]: Dataset iterator.\\n        \\\"\\\"\\\"\\n        # NOTE: hf iterable dataset uses worker ids while map dataset does not\\n        # NOTE: add worker id and shuffle to the map dataset\\n        # https://github.com/huggingface/datasets/blob/4.0.0/src/datasets/iterable_dataset.py#L2214\\n\\n        raise NotImplementedError()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    \\\"\\\"\\\"\\n    python -m llamafactory.v1.core.data_engine --train_dataset data/v1_sft_demo.yaml\\n    python -m llamafactory.v1.core.data_engine --train_dataset data/v1_dpo_demo.yaml\\n    \\\"\\\"\\\"\\n    from ..config.arg_parser import get_args\\n\\n    _, data_args, *_ = get_args()\\n    data_engine = DataEngine(data_args.train_dataset)\\n    print(data_engine[0])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/model_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"92f7242af6c4b45ea41a0efb9245abe6b3f0e09f3a384fbac3652b73c082877f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"The definition of model engine.\\n\\nHow to use:\\nmodel_engine = ModelEngine(model_args, is_train=True)\\nmodel_engine.processor: Get the tokenizer or multi-modal processor.\\nmodel_engine.renderer: Get the renderer.\\nmodel_engine.model_config: Get the model configuration.\\nmodel_engine.model: Get the HF model.\\n\\nInit workflow:\\n1. Init processor.\\n2. Init render.\\n2. Init model config.\\n3. Init model.\\n4. Init adapter.\\n\\\"\\\"\\\"\\n\\nimport torch\\nfrom accelerate import init_empty_weights\\nfrom transformers import AutoConfig, AutoProcessor\\n\\nfrom ..accelerator.helper import DeviceType\\nfrom ..accelerator.interface import DistributedInterface\\nfrom ..config.model_args import ModelArguments, ModelClass\\nfrom ..utils import logging\\nfrom ..utils.helper import get_tokenizer, is_tokenizer\\nfrom ..utils.types import HFConfig, HFModel, Processor\\nfrom .rendering import Renderer\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass ModelEngine:\\n    \\\"\\\"\\\"Model engine.\\n\\n    Args:\\n        model_args: Model arguments.\\n        is_train: Whether to train the model.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        model_args: ModelArguments,\\n        is_train: bool = False,\\n    ) -> None:\\n        self.args = model_args\\n        \\\"\\\"\\\"Model arguments.\\\"\\\"\\\"\\n        self.is_train = is_train\\n        \\\"\\\"\\\"Whether to train the model.\\\"\\\"\\\"\\n        self.processor = self._init_processor()\\n        \\\"\\\"\\\"Tokenizer or multi-modal processor.\\\"\\\"\\\"\\n        self._sync_chat_template()\\n        self.model_config = self._init_model_config()\\n        \\\"\\\"\\\"Model configuration.\\\"\\\"\\\"\\n        self.renderer = Renderer(self.processor)\\n        \\\"\\\"\\\"Renderer.\\\"\\\"\\\"\\n        self._deepspeed_zero3_enabled = False\\n\\n        try:\\n            from ..plugins.model_plugins.deepspeed_utils import (\\n                is_deepspeed_zero3_enabled,\\n                setup_deepspeed_zero3_model_loading,\\n                teardown_deepspeed_zero3_model_loading,\\n            )\\n\\n            self._deepspeed_zero3_enabled = self.is_train and is_deepspeed_zero3_enabled()\\n        except ImportError:\\n            pass\\n\\n        if self._deepspeed_zero3_enabled:\\n            plugin = setup_deepspeed_zero3_model_loading()\\n            try:\\n                self.model = self._init_model()\\n            finally:\\n                teardown_deepspeed_zero3_model_loading(plugin)\\n        else:\\n            self.model = self._init_model()\\n\\n    def _init_processor(self) -> Processor:\\n        \\\"\\\"\\\"Init processor.\\n\\n        NOTE: Transformers v5 always use fast tokenizer.\\n        https://github.com/huggingface/transformers/blob/v5.0.0rc1/src/transformers/models/auto/tokenization_auto.py#L642\\n        \\\"\\\"\\\"\\n        return AutoProcessor.from_pretrained(\\n            self.args.model,\\n            trust_remote_code=self.args.trust_remote_code,\\n        )\\n\\n    def _sync_chat_template(self) -> None:\\n        \\\"\\\"\\\"Sync chat_template and inject custom_chat_template.\\\"\\\"\\\"\\n        tokenizer = get_tokenizer(self.processor)\\n        if not is_tokenizer(self.processor) and not getattr(self.processor, \\\"chat_template\\\", None):\\n            if getattr(tokenizer, \\\"chat_template\\\", None):\\n                self.processor.chat_template = tokenizer.chat_template\\n\\n        if self.args.custom_chat_template:\\n            if not is_tokenizer(self.processor):\\n                self.processor.chat_template = self.args.custom_chat_template\\n            tokenizer.chat_template = self.args.custom_chat_template\\n\\n    def _init_model_config(self) -> HFConfig:\\n        \\\"\\\"\\\"Init model config.\\\"\\\"\\\"\\n        return AutoConfig.from_pretrained(\\n            self.args.model,\\n            trust_remote_code=self.args.trust_remote_code,\\n        )\\n\\n    def _init_model(self) -> HFModel:\\n        \\\"\\\"\\\"Init model.\\n\\n        Transformers can choose the proper model init context.\\n        https://github.com/huggingface/transformers/blob/v5.0.0rc0/src/transformers/modeling_utils.py#L3538\\n        \\\"\\\"\\\"\\n        if self.args.init_config is not None:\\n            from ..plugins.model_plugins.initialization import InitPlugin\\n\\n            init_device = InitPlugin(self.args.init_config.name)()\\n        else:\\n            init_device = DistributedInterface().current_device\\n\\n        init_kwargs = {} if self._deepspeed_zero3_enabled else {\\\"device_map\\\": init_device}\\n        logger.info_rank0(f\\\"Using attention implementation: {self.args.flash_attn}.\\\")\\n\\n        if self.args.quant_config is not None:\\n            from ..plugins.model_plugins.quantization import QuantizationPlugin\\n\\n            init_kwargs = QuantizationPlugin(self.args.quant_config.name)(\\n                init_kwargs=init_kwargs,\\n                quant_config=self.args.quant_config,\\n                is_trainable=self.is_train,\\n            )\\n\\n        if self.args.model_class == ModelClass.LLM:\\n            from transformers import AutoModelForCausalLM, AutoModelForImageTextToText\\n\\n            # AutoModelForMultimodalLM (audio / other multimodal LMs, e.g. Qwen2-Audio) was added in\\n            # a newer transformers; fall back gracefully when it is absent (e.g. 4.57.1).\\n            try:\\n                from transformers import AutoModelForMultimodalLM\\n            except ImportError:\\n                AutoModelForMultimodalLM = None\\n\\n            cfg_type = type(self.model_config)\\n            if cfg_type in AutoModelForImageTextToText._model_mapping.keys():\\n                AutoClass = AutoModelForImageTextToText\\n            elif AutoModelForMultimodalLM is not None and cfg_type in AutoModelForMultimodalLM._model_mapping.keys():\\n                # Audio / other multimodal LMs (e.g. Qwen2-Audio) live here, not in CausalLM.\\n                AutoClass = AutoModelForMultimodalLM\\n            else:\\n                AutoClass = AutoModelForCausalLM\\n\\n        elif self.args.model_class == ModelClass.CLS:\\n            from transformers import AutoModelForTokenClassification\\n\\n            self.model_config.num_labels = 1\\n            self.model_config.classifier_dropout = 0.0\\n            text_config = getattr(self.model_config, \\\"text_config\\\", None)\\n            if text_config is not None:\\n                text_config.num_labels = 1\\n                text_config.classifier_dropout = 0.0\\n            AutoClass = AutoModelForTokenClassification\\n        else:\\n            from transformers import AutoModel\\n\\n            AutoClass = AutoModel\\n\\n        if init_device.type == DeviceType.META:\\n            assert self.args.quant_config is None, \\\"Quantization is not supported with meta device.\\\"\\n            with init_empty_weights():\\n                model = AutoClass.from_config(self.model_config, attn_implementation=self.args.flash_attn)\\n        else:\\n            model = AutoClass.from_pretrained(\\n                self.args.model,\\n                config=self.model_config,\\n                dtype=\\\"auto\\\",\\n                attn_implementation=self.args.flash_attn,\\n                trust_remote_code=self.args.trust_remote_code,\\n                **init_kwargs,\\n            )\\n\\n        init_mode = self.args.init_config.name if self.args.init_config is not None else \\\"init_on_default\\\"\\n        model._init_mode = init_mode\\n\\n        if hasattr(model, \\\"thinker\\\"):\\n            model = model.thinker\\n            model._init_mode = init_mode\\n\\n        if self.args.peft_config is None:\\n            if self.is_train:\\n                logger.info_rank0(\\\"Fine-tuning mode: full tuning\\\")\\n                model = model.to(torch.float32)\\n            else:\\n                logger.info_rank0(\\\"Inference the original model\\\")\\n        else:\\n            if self.args.peft_config.name == \\\"lora\\\" and init_mode == \\\"init_on_meta\\\":\\n                raise ValueError(\\\"Currently lora stage does not support loading model by meta.\\\")\\n\\n            from ..plugins.model_plugins.peft import PeftPlugin\\n\\n            model = PeftPlugin(self.args.peft_config.name)(\\n                model,\\n                peft_config=self.args.peft_config,\\n                is_train=self.is_train,\\n            )\\n\\n        if self.args.kernel_config is not None:\\n            from ..plugins.model_plugins.kernels.interface import apply_kernels\\n\\n            model = apply_kernels(model, self.args.kernel_config, require_logits=self.is_train)\\n\\n        return model\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    \\\"\\\"\\\"\\n    python -m llamafactory.v1.core.model_engine --model llamafactory/tiny-random-qwen2.5\\n    \\\"\\\"\\\"\\n    from ..config.arg_parser import get_args\\n\\n    model_args, *_ = get_args()\\n    model_engine = ModelEngine(model_args=model_args)\\n    print(model_engine.processor)\\n    print(model_engine.model_config)\\n    print(model_engine.model)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/rendering/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1dd1991cc46e4a26acf2b20191df93f5e8b35b20b99a1a8ec9707c2b57839a11\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Rendering: turn a v1 ``Sample`` into a tokenized ``ModelInput``.\\n\\nPublic entry point is :class:`Renderer`. Internals are split by concern:\\n``format`` (message<->HF conversion) and ``escape`` (special-token escaping). Assistant supervision\\nis located by a prompt/full token diff rather than a per-model marker table.\\n\\\"\\\"\\\"\\n\\nfrom .rendering import Renderer\\n\\n\\n__all__ = [\\\"Renderer\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/rendering/escape.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a39a66e271ee87c2117f4623c7b1a950e46541a0a622738909e24c63c4aacb2a\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Special-token escaping (prompt-injection hardening).\\n\\nNeutralizes control-token strings (``<|im_start|>``, ``<|image_pad|>`` ...) that appear literally\\nin user-controlled text, so a crafted dataset cannot inject role markers or media placeholders\\ninto the rendered stream. A no-op for normal data.\\n\\\"\\\"\\\"\\n\\nimport json\\n\\nfrom ...utils.types import Message\\n\\n\\ndef _special_token_strings(tokenizer) -> list[str]:\\n    \\\"\\\"\\\"Strings the tokenizer encodes to a reserved/special id.\\n\\n    Such strings must be neutralized if they appear literally in user text. Derived from\\n    ``added_tokens_decoder`` so it covers every control token of the model (``<|im_start|>``,\\n    ``<|image_pad|>``, ``<tts_pad>`` ...), not only ``<|...|>``-shaped ones. Sorted longest-first\\n    so nested matches escape correctly.\\n    \\\"\\\"\\\"\\n    specials = [str(t) for t in tokenizer.added_tokens_decoder.values() if getattr(t, \\\"special\\\", False)]\\n    return sorted((s for s in specials if len(s) >= 2), key=len, reverse=True)\\n\\n\\ndef _escape_special(text: str, specials: list[str], special_ids: set[int], tokenizer) -> str:\\n    \\\"\\\"\\\"Break any special-token string in user text by inserting U+200B after its first char.\\n\\n    No-op (no tokenization cost) when the text contains no special-token string. When it does,\\n    self-validate that the result no longer encodes to a special id -- some normalizers strip\\n    zero-width chars and would resurrect the collision -- and raise if it does.\\n    \\\"\\\"\\\"\\n    if not any(sp in text for sp in specials):\\n        return text\\n    out = text\\n    for sp in specials:\\n        if sp in out:\\n            # Insert a zero-width space (U+200B) after the first char to break the exact\\n            # special-token string match while keeping the text visually/semantically intact.\\n            out = out.replace(sp, sp[0] + \\\"\\\\u200b\\\" + sp[1:])\\n    if special_ids.intersection(tokenizer(out, add_special_tokens=False)[\\\"input_ids\\\"]):\\n        raise ValueError(\\n            \\\"special-token escape failed: the tokenizer normalized away the break char; \\\"\\n            \\\"user text contains a literal control token that cannot be safely neutralized.\\\"\\n        )\\n    return out\\n\\n\\ndef _escape_special_in_messages(\\n    messages: list[Message], specials: list[str], special_ids: set[int], tokenizer\\n) -> list[Message]:\\n    \\\"\\\"\\\"Return messages with special-token strings neutralized in user-controlled literal text.\\n\\n    Covers ``text``/``reasoning`` block values and string values inside ``tool_call`` arguments.\\n    \\\"\\\"\\\"\\n    if not specials:\\n        return messages\\n    escaped: list[Message] = []\\n    for message in messages:\\n        new_content = []\\n        for content in message[\\\"content\\\"]:\\n            if content[\\\"type\\\"] in (\\\"text\\\", \\\"reasoning\\\"):\\n                new_content.append(\\n                    {**content, \\\"value\\\": _escape_special(content[\\\"value\\\"], specials, special_ids, tokenizer)}\\n                )\\n            elif content[\\\"type\\\"] == \\\"tool_call\\\":\\n                try:\\n                    tc = json.loads(content[\\\"value\\\"])\\n                except (json.JSONDecodeError, TypeError):\\n                    new_content.append(content)\\n                    continue\\n                # A tool_call value that is valid JSON but not an object (list/str/int) carries no\\n                # escapable argument strings -- pass it through untouched rather than crash on .get().\\n                if isinstance(tc, dict):\\n                    args = tc.get(\\\"arguments\\\")\\n                    if isinstance(args, dict):\\n                        tc[\\\"arguments\\\"] = {\\n                            k: (_escape_special(v, specials, special_ids, tokenizer) if isinstance(v, str) else v)\\n                            for k, v in args.items()\\n                        }\\n                    new_content.append({**content, \\\"value\\\": json.dumps(tc)})\\n                else:\\n                    new_content.append(content)\\n            else:\\n                new_content.append(content)\\n        escaped.append({**message, \\\"content\\\": new_content})\\n    return escaped\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/rendering/format.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30e029b7e8726c4d85eb638274a71a658ac0c77603c7dbd26f41105cbbf33480\",\"content\":\"# Copyright 2026 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Message <-> HF-template plumbing for rendering.\\n\\nPure, stateless helpers: convert v1 ``Message`` to HF chat-template format, extract/count media, and\\nguard media placeholder counts. No tokenization policy decisions live here -- only mechanical\\nconversion used by ``rendering.py``.\\n\\\"\\\"\\\"\\n\\nimport json\\n\\nfrom ...utils.helper import get_tokenizer\\nfrom ...utils.types import Message, Processor\\n\\n\\n_FALLBACK_CHATML_JINJA = (\\n    \\\"{% for message in messages %}\\\"\\n    \\\"{{'<|im_start|>' + message['role'] + '\\\\n' + message['content'] + '<|im_end|>' + '\\\\n'}}\\\"\\n    \\\"{% endfor %}\\\"\\n    \\\"{% if add_generation_prompt %}\\\"\\n    \\\"{{'<|im_start|>assistant\\\\n'}}\\\"\\n    \\\"{% endif %}\\\"\\n)\\n\\n\\ndef _to_hf_messages(messages: list[Message], is_multimodal: bool = False) -> list[dict]:\\n    \\\"\\\"\\\"Convert v1 Message format to HF format for apply_chat_template.\\\"\\\"\\\"\\n    hf_messages = []\\n    for message in messages:\\n        tool_calls: list[dict] = []\\n        reasoning_content = \\\"\\\"\\n\\n        if is_multimodal:\\n            hf_content = []\\n            for content in message[\\\"content\\\"]:\\n                if content[\\\"type\\\"] == \\\"text\\\":\\n                    hf_content.append({\\\"type\\\": \\\"text\\\", \\\"text\\\": content[\\\"value\\\"]})\\n                elif content[\\\"type\\\"] == \\\"reasoning\\\":\\n                    reasoning_content += content[\\\"value\\\"]\\n                elif content[\\\"type\\\"] == \\\"tool_call\\\":\\n                    try:\\n                        tc = json.loads(content[\\\"value\\\"])\\n                    except json.JSONDecodeError as e:\\n                        raise ValueError(f\\\"tool_call value is not valid JSON: {content['value']!r}\\\") from e\\n                    if not isinstance(tc, dict) or \\\"name\\\" not in tc or \\\"arguments\\\" not in tc:\\n                        raise ValueError(\\n                            f\\\"tool_call must be a JSON object with 'name' and 'arguments' keys, got {tc!r}\\\"\\n                        )\\n                    tool_calls.append(\\n                        {\\\"type\\\": \\\"function\\\", \\\"function\\\": {\\\"name\\\": tc[\\\"name\\\"], \\\"arguments\\\": tc[\\\"arguments\\\"]}}\\n                    )\\n                elif content[\\\"type\\\"] == \\\"image_url\\\":\\n                    hf_content.append({\\\"type\\\": \\\"image\\\", \\\"image\\\": content[\\\"value\\\"]})\\n                elif content[\\\"type\\\"] == \\\"video_url\\\":\\n                    hf_content.append({\\\"type\\\": \\\"video\\\", \\\"video\\\": content[\\\"value\\\"]})\\n                elif content[\\\"type\\\"] == \\\"audio_url\\\":\\n                    hf_content.append({\\\"type\\\": \\\"audio\\\", \\\"audio\\\": content[\\\"value\\\"]})\\n            hf_msg = {\\\"role\\\": message[\\\"role\\\"], \\\"content\\\": hf_content}\\n        else:\\n            text = \\\"\\\"\\n            for content in message[\\\"content\\\"]:\\n                if content[\\\"type\\\"] == \\\"text\\\":\\n                    text += content[\\\"value\\\"]\\n                elif content[\\\"type\\\"] == \\\"reasoning\\\":\\n                    reasoning_content += content[\\\"value\\\"]\\n                elif content[\\\"type\\\"] == \\\"tool_call\\\":\\n                    try:\\n                        tc = json.loads(content[\\\"value\\\"])\\n                    except json.JSONDecodeError as e:\\n                        raise ValueError(f\\\"tool_call value is not valid JSON: {content['value']!r}\\\") from e\\n                    if not isinstance(tc, dict) or \\\"name\\\" not in tc or \\\"arguments\\\" not in tc:\\n                        raise ValueError(\\n                            f\\\"tool_call must be a JSON object with 'name' and 'arguments' keys, got {tc!r}\\\"\\n                        )\\n                    tool_calls.append(\\n                        {\\\"type\\\": \\\"function\\\", \\\"function\\\": {\\\"name\\\": tc[\\\"name\\\"], \\\"arguments\\\": tc[\\\"arguments\\\"]}}\\n                    )\\n            hf_msg = {\\\"role\\\": message[\\\"role\\\"], \\\"content\\\": text}\\n\\n        if tool_calls:\\n            hf_msg[\\\"tool_calls\\\"] = tool_calls\\n        if reasoning_content:\\n            hf_msg[\\\"reasoning_content\\\"] = reasoning_content\\n\\n        hf_messages.append(hf_msg)\\n    return hf_messages\\n\\n\\ndef _extract_media_from_messages(messages: list[Message]) -> tuple[list, list, list]:\\n    \\\"\\\"\\\"Extract image, video and audio paths/values from messages in order.\\\"\\\"\\\"\\n    images, videos, audios = [], [], []\\n    for message in messages:\\n        for content in message[\\\"content\\\"]:\\n            if content[\\\"type\\\"] == \\\"image_url\\\":\\n                images.append(content[\\\"value\\\"])\\n            elif content[\\\"type\\\"] == \\\"video_url\\\":\\n                videos.append(content[\\\"value\\\"])\\n            elif content[\\\"type\\\"] == \\\"audio_url\\\":\\n                audios.append(content[\\\"value\\\"])\\n    return images, videos, audios\\n\\n\\ndef _count_media_in_messages(messages: list[Message]) -> tuple[int, int, int]:\\n    \\\"\\\"\\\"Count total images, videos and audios in messages.\\\"\\\"\\\"\\n    n_images, n_videos, n_audios = 0, 0, 0\\n    for message in messages:\\n        for content in message[\\\"content\\\"]:\\n            if content[\\\"type\\\"] == \\\"image_url\\\":\\n                n_images += 1\\n            elif content[\\\"type\\\"] == \\\"video_url\\\":\\n                n_videos += 1\\n            elif content[\\\"type\\\"] == \\\"audio_url\\\":\\n                n_audios += 1\\n    return n_images, n_videos, n_audios\\n\\n\\ndef _load_audios(values: list, sampling_rate: int) -> list:\\n    \\\"\\\"\\\"Load audio inputs into mono waveforms resampled to ``sampling_rate``.\\\"\\\"\\\"\\n    import numpy as np\\n    import torchaudio\\n\\n    results = []\\n    for value in values:\\n        if isinstance(value, np.ndarray):\\n            results.append(value)\\n            continue\\n\\n        waveform, sr = torchaudio.load(value)\\n        if waveform.shape[0] > 1:  # downmix to mono\\n            waveform = waveform.mean(dim=0, keepdim=True)\\n        if sr != sampling_rate:\\n            waveform = torchaudio.functional.resample(waveform, sr, sampling_rate)\\n        results.append(waveform.squeeze(0).numpy())\\n    return results\\n\\n\\ndef _check_placeholder_counts(\\n    processor: \\\"Processor\\\", full_text: str, n_images: int, n_videos: int, n_audios: int = 0\\n) -> None:\\n    \\\"\\\"\\\"Guard: every media placeholder in the rendered text must originate from a media block.\\\"\\\"\\\"\\n    tokenizer = get_tokenizer(processor)\\n    for attr, count, kind in (\\n        (\\\"image_token_id\\\", n_images, \\\"image\\\"),\\n        (\\\"video_token_id\\\", n_videos, \\\"video\\\"),\\n        (\\\"audio_token_id\\\", n_audios, \\\"audio\\\"),\\n    ):\\n        tid = getattr(processor, attr, None)\\n        if tid is None:\\n            tid = getattr(tokenizer, attr, None)\\n        if tid is None:\\n            continue\\n        placeholder = tokenizer.convert_ids_to_tokens(tid)\\n        seen = full_text.count(placeholder)\\n        if seen != count:\\n            raise ValueError(\\n                f\\\"{kind} placeholder count ({seen}) != number of {kind} blocks ({count}); \\\"\\n                \\\"media must be provided via image_url/video_url content blocks.\\\"\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/rendering/rendering.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"57d715a5f1f3b215d6d52c47d35e2e76a6cffc073220dc32475c29691588ba16\",\"content\":\"# Copyright 2026 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Rendering: turn a v1 ``Sample`` into a tokenized ``ModelInput``.\\n\\nThis module is the orchestration + public API (``Renderer``). The mechanical pieces live in\\nsibling modules:\\n  - ``format``  -- v1<->HF message conversion\\n  - ``escape``  -- special-token escaping (prompt-injection hardening)\\n\\nNote: ``position_ids`` are assigned by ``process_samples`` (1-based); multimodal (mrope) position\\nids are expected to be recomputed by the model/trainer.\\n\\\"\\\"\\\"\\n\\nimport json\\n\\nimport numpy as np\\nimport torch\\n\\nfrom ...utils.constants import IGNORE_INDEX\\nfrom ...utils.helper import get_tokenizer, is_tokenizer\\nfrom ...utils.types import Message, ModelInput, Processor, Sample\\nfrom ..utils.collation import _MULTIMODAL_PASSTHROUGH_KEYS\\nfrom .escape import _escape_special, _escape_special_in_messages, _special_token_strings\\nfrom .format import (\\n    _FALLBACK_CHATML_JINJA,\\n    _check_placeholder_counts,\\n    _count_media_in_messages,\\n    _extract_media_from_messages,\\n    _load_audios,\\n    _to_hf_messages,\\n)\\n\\n\\ndef _render_messages(\\n    processor: Processor,\\n    messages: list[Message],\\n    tools: str | None = None,\\n    is_generate: bool = False,\\n    **kwargs,\\n) -> ModelInput:\\n    r\\\"\\\"\\\"Render messages using the model's own chat template, locating supervision by a prompt/full diff.\\n\\n    Note: ``position_ids`` are not produced here; ``process_samples`` assigns a 1-based range.\\n    \\\"\\\"\\\"\\n    tokenizer = get_tokenizer(processor)\\n    is_multimodal = not is_tokenizer(processor)\\n\\n    template_caller = processor if is_multimodal else tokenizer\\n    if not getattr(template_caller, \\\"chat_template\\\", None):\\n        template_caller.chat_template = _FALLBACK_CHATML_JINJA\\n\\n    # 0. Neutralize special-token strings in user-controlled text (no-op for normal data).\\n    specials = _special_token_strings(tokenizer)\\n    special_ids = {tid for tid, t in tokenizer.added_tokens_decoder.items() if getattr(t, \\\"special\\\", False)}\\n    messages = _escape_special_in_messages(messages, specials, special_ids, tokenizer)\\n\\n    hf_messages = _to_hf_messages(messages, is_multimodal=is_multimodal)\\n\\n    tools_parsed = None\\n    if tools:\\n        tools = _escape_special(tools, specials, special_ids, tokenizer)  # E3: tools text is user-controlled\\n        try:\\n            tools_parsed = json.loads(tools)\\n        except json.JSONDecodeError as e:\\n            raise ValueError(f\\\"tools is not valid JSON: {tools!r}\\\") from e\\n        if not isinstance(tools_parsed, list):\\n            tools_parsed = [tools_parsed]\\n\\n    if not is_generate and hf_messages and hf_messages[-1][\\\"role\\\"] == \\\"assistant\\\":\\n        kwargs[\\\"enable_thinking\\\"] = bool(hf_messages[-1].get(\\\"reasoning_content\\\"))\\n\\n    def _encode(hf_msgs: list[dict], src_msgs: list[Message], add_generation_prompt: bool):\\n        \\\"\\\"\\\"Render + tokenize, expanding media via the processor. Returns (input_ids, mm_outputs).\\\"\\\"\\\"\\n        text = template_caller.apply_chat_template(\\n            hf_msgs, tokenize=False, add_generation_prompt=add_generation_prompt, tools=tools_parsed, **kwargs\\n        )\\n        if is_multimodal and _count_media_in_messages(src_msgs) != (0, 0, 0):\\n            images, videos, audios = _extract_media_from_messages(src_msgs)\\n            # Every placeholder must come from a media block (escaping broke any literal ones).\\n            _check_placeholder_counts(processor, text, len(images), len(videos), len(audios))\\n            proc_kwargs = {\\\"return_tensors\\\": \\\"pt\\\"}\\n            if images:\\n                proc_kwargs[\\\"images\\\"] = images\\n            if videos:\\n                proc_kwargs[\\\"videos\\\"] = videos\\n            if audios:\\n                # Audio processors want decoded waveforms at the model's sampling rate, not paths.\\n                proc_kwargs[\\\"audio\\\"] = _load_audios(audios, processor.feature_extractor.sampling_rate)\\n            mm_outputs = processor(text=text, **proc_kwargs)\\n            return mm_outputs[\\\"input_ids\\\"][0].tolist(), mm_outputs\\n        return tokenizer(text, add_special_tokens=False)[\\\"input_ids\\\"], None\\n\\n    # 1. Full sequence (used verbatim), plus its multimodal feature outputs.\\n    input_ids, outputs = _encode(hf_messages, messages, add_generation_prompt=is_generate)\\n    n = len(input_ids)\\n\\n    def _attach_multimodal(result: ModelInput) -> None:\\n        if outputs is None:\\n            return\\n        for key in _MULTIMODAL_PASSTHROUGH_KEYS:\\n            if key in outputs:\\n                result[key] = outputs[key]\\n        mm_type_ids = outputs[\\\"mm_token_type_ids\\\"][0].tolist() if \\\"mm_token_type_ids\\\" in outputs else None\\n\\n        for attr, marker in ((\\\"image_token_id\\\", 1), (\\\"video_token_id\\\", 2), (\\\"audio_token_id\\\", 3)):\\n            token_id = getattr(processor, attr, None)\\n            if token_id is None:\\n                token_id = getattr(tokenizer, attr, None)\\n            if token_id is None or token_id not in input_ids:\\n                continue\\n            if mm_type_ids is not None and marker in mm_type_ids:\\n                continue\\n            if mm_type_ids is None:\\n                mm_type_ids = [0] * len(input_ids)\\n            mm_type_ids = [marker if tid == token_id else t for t, tid in zip(mm_type_ids, input_ids)]\\n\\n        if mm_type_ids is not None:\\n            result[\\\"mm_token_type_ids\\\"] = mm_type_ids\\n\\n    if is_generate:\\n        # Generation prompt only -- nothing is supervised.\\n        result = ModelInput(\\n            input_ids=input_ids,\\n            attention_mask=[1] * n,\\n            labels=[IGNORE_INDEX] * n,\\n            loss_weights=[0.0] * n,\\n        )\\n        _attach_multimodal(result)\\n        return result\\n\\n    if not messages or messages[-1][\\\"role\\\"] != \\\"assistant\\\":\\n        raise ValueError(\\n            \\\"training render expects the last message to be the supervised assistant turn; \\\"\\n            \\\"multi-turn conversations are split per turn in process_samples.\\\"\\n        )\\n\\n    prompt_ids, _ = _encode(hf_messages[:-1], messages[:-1], add_generation_prompt=True)\\n    if input_ids[: len(prompt_ids)] != prompt_ids:\\n        # The prompt must be a token-prefix of the full sequence for the diff to be valid. If a\\n        # template re-renders earlier turns when the final turn is appended, fail loud rather than\\n        # mislabel.\\n        raise ValueError(\\n            \\\"prompt is not a token-prefix of the full sequence; the chat template is not \\\"\\n            \\\"prefix-stable for this turn, so diff-based labeling is unsafe.\\\"\\n        )\\n\\n    weight = messages[-1].get(\\\"loss_weight\\\", 1.0)\\n    supervised = weight > 1e-6\\n    labels = [IGNORE_INDEX] * len(prompt_ids)\\n    loss_weights = [0.0] * len(prompt_ids)\\n    for tid in input_ids[len(prompt_ids) :]:\\n        labels.append(tid if supervised else IGNORE_INDEX)\\n        loss_weights.append(weight)\\n\\n    result = ModelInput(\\n        input_ids=input_ids,\\n        attention_mask=[1] * n,\\n        labels=labels,\\n        loss_weights=loss_weights,\\n    )\\n    _attach_multimodal(result)\\n    return result\\n\\n\\nclass Renderer:\\n    def __init__(self, processor: Processor, config=None):\\n        # ``config`` is accepted for call-site compatibility (ModelEngine passes the model config)\\n        # but is no longer needed: supervision is located by a prompt/full diff, not a per-model\\n        # marker table, so the renderer is model-agnostic.\\n        self.processor = processor\\n\\n    def render_messages(\\n        self,\\n        messages: list[Message],\\n        tools: str | None = None,\\n        is_generate: bool = False,\\n        **kwargs,\\n    ) -> ModelInput:\\n        \\\"\\\"\\\"Render messages to model input using apply_chat_template.\\n\\n        Args:\\n            messages: The messages to render. For training the last message must be the supervised\\n                assistant turn (use ``process_samples`` to split multi-turn conversations).\\n            tools: JSON string of tool definitions.\\n            is_generate: Whether to render for generation (adds generation prompt, no supervision).\\n            **kwargs: Extra chat-template kwargs (e.g. ``enable_thinking``) forwarded verbatim to\\n                ``apply_chat_template``; unset ones fall back to the template's own defaults. A\\n                supervised assistant turn carrying reasoning forces ``enable_thinking=True``.\\n\\n        Returns:\\n            ModelInput with input_ids, attention_mask, labels, and loss_weights.\\n        \\\"\\\"\\\"\\n        return _render_messages(self.processor, messages, tools, is_generate, **kwargs)\\n\\n    def get_dummy_media_fragment(self, modality: str) -> dict:\\n        \\\"\\\"\\\"Build (and cache) a minimal valid media fragment for ``modality`` (\\\"image\\\"|\\\"video\\\"|\\\"audio\\\").\\\"\\\"\\\"\\n        if modality not in (\\\"image\\\", \\\"video\\\", \\\"audio\\\"):\\n            raise ValueError(f\\\"Unsupported dummy media modality: {modality!r} (expected image/video/audio).\\\")\\n        if is_tokenizer(self.processor):\\n            raise RuntimeError(\\\"Cannot build a dummy media fragment for a text-only processor.\\\")\\n\\n        if not hasattr(self, \\\"_dummy_fragments\\\"):\\n            self._dummy_fragments: dict[str, dict] = {}\\n        if modality in self._dummy_fragments:\\n            return self._dummy_fragments[modality]\\n\\n        from PIL import Image as _PILImage\\n\\n        if modality == \\\"image\\\":\\n            media_block = {\\\"type\\\": \\\"image_url\\\", \\\"value\\\": _PILImage.new(\\\"RGB\\\", (64, 64))}\\n            target, presence_key = 1, \\\"pixel_values\\\"\\n        elif modality == \\\"video\\\":\\n            # A minimal clip: the temporal patch size is typically 2, so provide two frames.\\n            media_block = {\\\"type\\\": \\\"video_url\\\", \\\"value\\\": np.zeros((2, 64, 64, 3), dtype=np.uint8)}\\n            target, presence_key = 2, \\\"pixel_values_videos\\\"\\n        else:\\n            # A short synthetic waveform at the model's sampling rate; the feature extractor pads it.\\n            sr = self.processor.feature_extractor.sampling_rate\\n            media_block = {\\\"type\\\": \\\"audio_url\\\", \\\"value\\\": np.zeros(sr // 10, dtype=np.float32)}\\n            target, presence_key = 3, \\\"input_features\\\"\\n\\n        messages: list[Message] = [\\n            {\\\"role\\\": \\\"user\\\", \\\"content\\\": [media_block]},\\n            {\\\"role\\\": \\\"assistant\\\", \\\"content\\\": [{\\\"type\\\": \\\"text\\\", \\\"value\\\": \\\"ok\\\"}]},\\n        ]\\n        rendered = self.render_messages(messages)\\n\\n        mm_type_ids = rendered.get(\\\"mm_token_type_ids\\\")\\n        if not mm_type_ids or target not in mm_type_ids or presence_key not in rendered:\\n            raise RuntimeError(f\\\"Processor did not emit {modality} placeholder tokens for the dummy sample.\\\")\\n\\n        positions = [i for i, t in enumerate(mm_type_ids) if t == target]\\n        # Include the surrounding start/end delimiters (vision_start/end or audio_bos/eos) so the\\n        # fragment matches exactly what the template emits around real media.\\n        lo = max(positions[0] - 1, 0)\\n        hi = min(positions[-1] + 2, len(rendered[\\\"input_ids\\\"]))\\n\\n        fragment: dict = {\\n            \\\"input_ids\\\": list(rendered[\\\"input_ids\\\"][lo:hi]),\\n            \\\"mm_token_type_ids\\\": list(mm_type_ids[lo:hi]),\\n        }\\n\\n        for key in _MULTIMODAL_PASSTHROUGH_KEYS:\\n            if key in rendered:\\n                fragment[key] = rendered[key]\\n\\n        self._dummy_fragments[modality] = fragment\\n        return fragment\\n\\n    def process_samples(self, samples: list[Sample]) -> list[ModelInput]:\\n        \\\"\\\"\\\"Process samples to model input.\\n\\n        Multi-turn SFT conversations are already prefix-split in the data layer (DataEngine), so each\\n        ``messages`` sample is rendered once -- the diff-based renderer supervises only its last\\n        assistant turn.\\n\\n        Args:\\n            samples: The samples to process.\\n\\n        Returns:\\n            List of processed model inputs.\\n        \\\"\\\"\\\"\\n        model_inputs = []\\n        for sample in samples:\\n            rendered: list[ModelInput] = []\\n            if \\\"messages\\\" in sample:\\n                model_input = self.render_messages(sample[\\\"messages\\\"], sample.get(\\\"tools\\\"))\\n                model_input[\\\"position_ids\\\"] = list(range(1, len(model_input[\\\"input_ids\\\"]) + 1))\\n                rendered.append(model_input)\\n            elif \\\"chosen_messages\\\" in sample and \\\"rejected_messages\\\" in sample:\\n                chosen_input = self.render_messages(sample[\\\"chosen_messages\\\"], sample.get(\\\"tools\\\"))\\n                rejected_input = self.render_messages(sample[\\\"rejected_messages\\\"], sample.get(\\\"tools\\\"))\\n                chosen_input[\\\"token_type_ids\\\"] = [1] * len(chosen_input[\\\"input_ids\\\"])\\n                rejected_input[\\\"token_type_ids\\\"] = [2] * len(rejected_input[\\\"input_ids\\\"])\\n                model_input = ModelInput(\\n                    input_ids=chosen_input[\\\"input_ids\\\"] + rejected_input[\\\"input_ids\\\"],\\n                    attention_mask=chosen_input[\\\"attention_mask\\\"] + rejected_input[\\\"attention_mask\\\"],\\n                    labels=chosen_input[\\\"labels\\\"] + rejected_input[\\\"labels\\\"],\\n                    loss_weights=chosen_input[\\\"loss_weights\\\"] + rejected_input[\\\"loss_weights\\\"],\\n                    token_type_ids=chosen_input[\\\"token_type_ids\\\"] + rejected_input[\\\"token_type_ids\\\"],\\n                )\\n                # chosen and rejected are independent sequences; position ids must restart at 1 for\\n                # each (a single continuous range would offset rejected's positional embeddings).\\n                model_input[\\\"position_ids\\\"] = list(range(1, len(chosen_input[\\\"input_ids\\\"]) + 1)) + list(\\n                    range(1, len(rejected_input[\\\"input_ids\\\"]) + 1)\\n                )\\n\\n                for key in _MULTIMODAL_PASSTHROUGH_KEYS:\\n                    tensors = [inp[key] for inp in (chosen_input, rejected_input) if key in inp]\\n                    if tensors:\\n                        model_input[key] = torch.cat(tensors, dim=0)\\n\\n                if \\\"mm_token_type_ids\\\" in chosen_input or \\\"mm_token_type_ids\\\" in rejected_input:\\n                    chosen_mm = chosen_input.get(\\\"mm_token_type_ids\\\", [0] * len(chosen_input[\\\"input_ids\\\"]))\\n                    rejected_mm = rejected_input.get(\\\"mm_token_type_ids\\\", [0] * len(rejected_input[\\\"input_ids\\\"]))\\n                    model_input[\\\"mm_token_type_ids\\\"] = chosen_mm + rejected_mm\\n\\n                rendered.append(model_input)\\n            else:\\n                raise ValueError(\\\"No valid messages or chosen_messages/rejected_messages found in sample.\\\")\\n\\n            for model_input in rendered:\\n                if \\\"extra_info\\\" in sample:\\n                    model_input[\\\"extra_info\\\"] = sample[\\\"extra_info\\\"]\\n                if \\\"_dataset_name\\\" in sample:\\n                    model_input[\\\"_dataset_name\\\"] = sample[\\\"_dataset_name\\\"]\\n                model_inputs.append(model_input)\\n\\n        return model_inputs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/utils/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/utils/batching.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cba0a8f3a99420f545631dbc78105225fdf4490eb56fbd238bfdb83eed974cb9\",\"content\":\"# Copyright 2026 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Batching utils supports stateful dataloader.\\n\\n1. Init stateful dataloader (tokenize)\\n2. Add to buffer\\n3. Yield batch indexes (micro batch * grad acc)\\n    a) non pack + non dynamic\\n    b) non pack + dynamic\\n    c) pack + non dynamic\\n    d) pack + dynamic\\n\\\"\\\"\\\"\\n\\nfrom collections.abc import Iterator\\nfrom typing import Any\\n\\nimport torch\\nfrom torch.utils.data import default_collate\\nfrom torchdata.stateful_dataloader import StatefulDataLoader\\nfrom torchdata.stateful_dataloader.sampler import StatefulDistributedSampler\\n\\nfrom ...accelerator.helper import ReduceOp\\nfrom ...accelerator.interface import Dim, DistributedInterface\\nfrom ...config import BatchingStrategy\\nfrom ...utils import logging\\nfrom ...utils.constants import IGNORE_INDEX\\nfrom ...utils.helper import is_tokenizer\\nfrom ...utils.objects import StatefulBuffer\\nfrom ...utils.types import BatchInfo, BatchInput, ModelInput, Tensor, TorchDataset\\nfrom ..rendering import Renderer\\nfrom .collation import _MULTIMODAL_PASSTHROUGH_KEYS, pad_and_truncate\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n__all__ = [\\\"BatchGenerator\\\"]\\n\\n\\n# (modality, presence/feature key, grid key, mm_token_type_ids marker) for encoder-tower alignment.\\n# The presence key is what survives collation when the modality is present; the grid key is unused\\n# here (kept for parity with the collation specs). Audio carries no grid -- feature_attention_mask\\n# rides along as a passthrough feature.\\n_ALIGN_MODALITIES = (\\n    (\\\"image\\\", \\\"pixel_values\\\", \\\"image_grid_thw\\\", 1),\\n    (\\\"video\\\", \\\"pixel_values_videos\\\", \\\"video_grid_thw\\\", 2),\\n    (\\\"audio\\\", \\\"input_features\\\", \\\"feature_attention_mask\\\", 3),\\n)\\n\\n\\ndef _collate_micro_batch(micro_batch: list[ModelInput], cutoff_len: int) -> BatchInput:\\n    \\\"\\\"\\\"Pad/truncate then collate one micro batch (text fields stacked, MM features dim-0 concat).\\\"\\\"\\\"\\n    padded = pad_and_truncate(micro_batch, cutoff_len)\\n    standard_samples = [{k: v for k, v in s.items() if k not in _MULTIMODAL_PASSTHROUGH_KEYS} for s in padded]\\n    collated = default_collate(standard_samples)\\n    for key in _MULTIMODAL_PASSTHROUGH_KEYS:\\n        tensors = [s[key] for s in padded if key in s]\\n        if tensors:\\n            collated[key] = torch.cat(tensors, dim=0)\\n    return collated\\n\\n\\ndef _inject_dummy_into_collated(collated: BatchInput, fragment: dict, marker: int) -> None:\\n    \\\"\\\"\\\"Append a zero-loss dummy media fragment to an already-collated micro batch, in place.\\n\\n    Operates *after* pad_and_truncate so it reflects post-truncation presence: an image whose\\n    placeholder tokens were partially cut is deleted by ``_align_multimodal_on_truncation``,\\n    turning that sample text-only -- which must be detected here (not before truncation) or the\\n    vision-tower call count still desyncs across ranks.\\n\\n    The dummy tokens are appended (extra columns) into row 0 only; other rows get padding there.\\n    Causal attention keeps every real token's logits unchanged; the dummy carries IGNORE_INDEX\\n    labels and zero loss weight, so it contributes nothing to the loss while forcing the (FSDP-\\n    sharded) vision tower to run.\\n    \\\"\\\"\\\"\\n    bsz, seqlen = collated[\\\"input_ids\\\"].shape\\n    frag_ids = torch.tensor(fragment[\\\"input_ids\\\"], dtype=collated[\\\"input_ids\\\"].dtype)\\n    frag_len = frag_ids.numel()\\n    frag_mm = torch.tensor(fragment[\\\"mm_token_type_ids\\\"], dtype=torch.long)\\n    new_len = seqlen + frag_len\\n\\n    def _grow(tensor: Tensor, pad_value, row0_tail=None) -> Tensor:\\n        out = torch.full((bsz, new_len), pad_value, dtype=tensor.dtype)\\n        out[:, :seqlen] = tensor\\n        if row0_tail is not None:\\n            out[0, seqlen:] = row0_tail.to(tensor.dtype)\\n        return out\\n\\n    collated[\\\"input_ids\\\"] = _grow(collated[\\\"input_ids\\\"], 0, frag_ids)\\n    collated[\\\"attention_mask\\\"] = _grow(collated[\\\"attention_mask\\\"], 0)\\n    collated[\\\"attention_mask\\\"][0, seqlen:] = 1\\n    collated[\\\"labels\\\"] = _grow(collated[\\\"labels\\\"], IGNORE_INDEX)  # dummy region stays ignored\\n    collated[\\\"loss_weights\\\"] = _grow(collated[\\\"loss_weights\\\"], 0.0)\\n    if \\\"position_ids\\\" in collated:\\n        pos = _grow(collated[\\\"position_ids\\\"], 0)\\n        pos[0, seqlen:] = torch.arange(seqlen + 1, new_len + 1, dtype=pos.dtype)\\n        collated[\\\"position_ids\\\"] = pos\\n\\n    mm = collated.get(\\\"mm_token_type_ids\\\")\\n    if mm is not None:\\n        collated[\\\"mm_token_type_ids\\\"] = _grow(mm, 0, frag_mm)\\n    else:\\n        mm = torch.zeros((bsz, new_len), dtype=torch.long)\\n        mm[0, seqlen:] = frag_mm\\n        collated[\\\"mm_token_type_ids\\\"] = mm\\n\\n    for key, value in fragment.items():\\n        if key in (\\\"input_ids\\\", \\\"mm_token_type_ids\\\"):\\n            continue\\n        collated[key] = torch.cat([collated[key], value], dim=0) if key in collated else value\\n\\n\\ndef default_collate_fn(\\n    buffer: StatefulBuffer, batch_info: BatchInfo, renderer: Renderer | None = None\\n) -> list[BatchInput] | None:\\n    micro_batch_size = batch_info[\\\"micro_batch_size\\\"]\\n    num_micro_batch = batch_info[\\\"num_micro_batch\\\"]\\n    cutoff_len = batch_info[\\\"cutoff_len\\\"]\\n    batch_size = micro_batch_size * num_micro_batch\\n    if len(buffer) < batch_size:\\n        return None\\n\\n    samples = buffer.get(batch_size)\\n    micro_batches = [samples[i * micro_batch_size : (i + 1) * micro_batch_size] for i in range(num_micro_batch)]\\n\\n    # Collate first; presence is judged on the *post-truncation* result, since truncation can\\n    # delete a partially-cut image and turn a sample text-only (see _inject_dummy_into_collated).\\n    batch = [_collate_micro_batch(mb, cutoff_len) for mb in micro_batches]\\n\\n    if renderer is not None and not is_tokenizer(renderer.processor):\\n        present = torch.zeros((num_micro_batch, len(_ALIGN_MODALITIES)), dtype=torch.int64)\\n        for i, collated in enumerate(batch):\\n            for m, (_, pixel_key, _, _) in enumerate(_ALIGN_MODALITIES):\\n                present[i, m] = int(pixel_key in collated)\\n\\n        present = DistributedInterface().all_reduce(present, op=ReduceOp.MAX, dim=Dim.DP)\\n\\n        for i, collated in enumerate(batch):\\n            for m, (modality, pixel_key, _, marker) in enumerate(_ALIGN_MODALITIES):\\n                if present[i, m] and pixel_key not in collated:\\n                    _inject_dummy_into_collated(collated, renderer.get_dummy_media_fragment(modality), marker)\\n\\n    return batch\\n\\n\\nclass BatchGenerator(Iterator):\\n    def __init__(\\n        self,\\n        dataset: TorchDataset,\\n        renderer: Renderer,\\n        micro_batch_size: int = 1,\\n        global_batch_size: int | None = None,\\n        cutoff_len: int = 2048,\\n        batching_workers: int = 0,\\n        batching_strategy: BatchingStrategy = BatchingStrategy.NORMAL,\\n        pin_memory: bool = True,\\n        drop_last: bool = True,\\n        seed: int = 42,\\n    ) -> None:\\n        self.dataset = dataset\\n        self.renderer = renderer\\n\\n        self.micro_batch_size = micro_batch_size\\n        self.global_batch_size = global_batch_size\\n        self.cutoff_len = cutoff_len\\n        self.batching_workers = batching_workers\\n        self.batching_strategy = batching_strategy\\n        self.pin_memory = pin_memory\\n        self.drop_last = drop_last\\n        self.seed = seed\\n        self._warned_truncation = False  # warn once when dropping fully-truncated (zero-loss) samples\\n        # TODO: support length and infinity\\n        dp_size = DistributedInterface().get_world_size(Dim.DP)\\n\\n        if self.global_batch_size is None:\\n            self.global_batch_size = dp_size * micro_batch_size\\n            self.num_micro_batch = 1\\n        elif self.global_batch_size % (dp_size * micro_batch_size) == 0:\\n            self.num_micro_batch = global_batch_size // dp_size // micro_batch_size\\n        else:\\n            raise ValueError(\\n                \\\"Global batch size must be divisible by DP size and micro batch size. \\\"\\n                f\\\"Got {global_batch_size} % ({dp_size} * {micro_batch_size}) != 0.\\\"\\n            )\\n\\n        if not self.drop_last:\\n            raise ValueError(\\\"Drop last must be True.\\\")\\n\\n        self._batch_info: BatchInfo = {\\n            \\\"micro_batch_size\\\": self.micro_batch_size,\\n            \\\"num_micro_batch\\\": self.num_micro_batch,\\n            \\\"cutoff_len\\\": self.cutoff_len,\\n        }\\n\\n        self._init_data_provider()\\n\\n        self._is_resuming: bool = False\\n        self._data_iter = iter(self._data_provider)\\n        self._buffer = StatefulBuffer()\\n\\n        logger.info_rank0(\\n            f\\\"Init unified data loader with global batch size {self.global_batch_size}, \\\"\\n            f\\\"micro batch size {self.micro_batch_size}, \\\"\\n            f\\\"num micro batch {self.num_micro_batch}, \\\"\\n            f\\\"cutoff len {self.cutoff_len}, \\\"\\n            f\\\"batching workers {self.batching_workers}, \\\"\\n            f\\\"batching strategy {self.batching_strategy}.\\\"\\n        )\\n\\n    def _init_data_provider(self) -> None:\\n        if len(self.dataset) != -1:\\n            sampler = StatefulDistributedSampler(\\n                self.dataset,\\n                num_replicas=DistributedInterface().get_world_size(Dim.DP),\\n                rank=DistributedInterface().get_rank(Dim.DP),\\n                shuffle=True,\\n                seed=self.seed,\\n                drop_last=self.drop_last,\\n            )\\n        else:\\n            raise NotImplementedError(\\\"Iterable dataset is not supported yet.\\\")\\n\\n        if self.batching_strategy == BatchingStrategy.NORMAL:\\n            batch_size = self.micro_batch_size * self.num_micro_batch\\n        else:\\n            from ...plugins.trainer_plugins.batching import BatchingPlugin\\n\\n            batch_size = BatchingPlugin(self.batching_strategy).get_data_provider_batch_size(self._batch_info)\\n\\n        generator_seed = torch.Generator()\\n        generator_seed.manual_seed(self.seed)\\n\\n        self._data_provider = StatefulDataLoader(\\n            self.dataset,\\n            batch_size=batch_size,\\n            sampler=sampler,\\n            num_workers=self.batching_workers,\\n            collate_fn=self.renderer.process_samples,\\n            pin_memory=self.pin_memory,\\n            pin_memory_device=DistributedInterface().current_device.type,\\n            drop_last=self.drop_last,\\n            generator=generator_seed,\\n        )\\n        if self.batching_strategy == BatchingStrategy.NORMAL:\\n            self._length = len(self._data_provider)\\n        else:\\n            from ...plugins.trainer_plugins.batching import BatchingPlugin\\n\\n            self._length = BatchingPlugin(self.batching_strategy).compute_length(self._data_provider, self._batch_info)\\n\\n    def __len__(self) -> int:\\n        return self._length\\n\\n    def __iter__(self):\\n        if not self._is_resuming:\\n            self._buffer.clear()\\n\\n        self._data_iter = iter(self._data_provider)\\n        self._is_resuming = False\\n        return self\\n\\n    def __next__(self):\\n        self._fill_buffer()\\n        batch = self._generate_batch()\\n        if batch is None:\\n            raise StopIteration\\n\\n        return batch\\n\\n    def _drop_unsupervised(self, samples: list[ModelInput]) -> list[ModelInput]:\\n        \\\"\\\"\\\"Drop samples whose supervised span is entirely beyond ``cutoff_len``.\\n\\n        Prefix-split puts the supervised tokens at the tail, and truncation keeps ``[:cutoff_len]``,\\n        so a sample longer than ``cutoff_len`` loses all supervision and would contribute a zero-loss\\n        (wasted) step. Only such over-length samples are at risk -- samples that fit within\\n        ``cutoff_len`` are never truncated and always keep supervision -- so they pass an O(1) length\\n        test before any ``loss_weights`` scan. Drop the at-risk, fully-masked ones and warn once.\\n        \\\"\\\"\\\"\\n        kept = []\\n        for sample in samples:\\n            if len(sample[\\\"input_ids\\\"]) > self.cutoff_len and not any(\\n                w > 1e-6 for w in sample[\\\"loss_weights\\\"][: self.cutoff_len]\\n            ):\\n                if not self._warned_truncation:\\n                    self._warned_truncation = True\\n                    logger.warning_rank0(\\n                        f\\\"Dropping training sample(s) whose supervised tokens fall entirely beyond \\\"\\n                        f\\\"cutoff_len={self.cutoff_len} (all loss masked after truncation). \\\"\\n                        \\\"Increase cutoff_len to keep them.\\\"\\n                    )\\n                continue\\n            kept.append(sample)\\n        return kept\\n\\n    def _fill_buffer(self) -> None:\\n        if self.batching_strategy == BatchingStrategy.NORMAL:\\n            while len(self._buffer) < self.micro_batch_size * self.num_micro_batch:\\n                try:\\n                    samples: list[ModelInput] = next(self._data_iter)\\n                except StopIteration:\\n                    break\\n\\n                self._buffer.put(self._drop_unsupervised(samples))\\n        else:\\n            from ...plugins.trainer_plugins.batching import BatchingPlugin\\n\\n            BatchingPlugin(self.batching_strategy).fill_buffer(self._buffer, self._batch_info, self._next_samples)\\n\\n    def _generate_batch(self) -> list[BatchInput] | None:\\n        if self.batching_strategy == BatchingStrategy.NORMAL:\\n            return default_collate_fn(self._buffer, self._batch_info, self.renderer)\\n        else:\\n            # Non-NORMAL strategies (dynamic / padding_free) collate ragged pixel tensors with a\\n            # bare default_collate and have no vision-tower alignment, so multimodal data would\\n            # crash or hang. Fail loud instead of silently mishandling it.\\n            if any(k in s for s in self._buffer.samples for k in _MULTIMODAL_PASSTHROUGH_KEYS):\\n                raise NotImplementedError(\\n                    f\\\"batching_strategy={self.batching_strategy.value!r} does not support multimodal data; \\\"\\n                    \\\"use the NORMAL strategy for image/video training.\\\"\\n                )\\n\\n            from ...plugins.trainer_plugins.batching import BatchingPlugin\\n\\n            return BatchingPlugin(self.batching_strategy).generate_batch(self._buffer, self._batch_info)\\n\\n    def _next_samples(self, restart: bool) -> list[ModelInput] | None:\\n        try:\\n            return next(self._data_iter)\\n        except StopIteration:\\n            if not restart:\\n                return None\\n\\n            # Dynamic batching may restart the provider to fill one token-budgeted batch.\\n            self._data_iter = iter(self._data_provider)\\n            try:\\n                return next(self._data_iter)\\n            except StopIteration:\\n                return None\\n\\n    def state_dict(self) -> dict[str, Any]:\\n        return {\\n            \\\"buffer\\\": self._buffer.state_dict(),\\n            \\\"data_provider\\\": self._data_provider.state_dict(),\\n        }\\n\\n    def load_state_dict(self, state: dict[str, Any]) -> None:\\n        self._buffer.load_state_dict(state[\\\"buffer\\\"])\\n        self._data_provider.load_state_dict(state[\\\"data_provider\\\"])\\n        self._is_resuming = True\\n\\n    def set_epoch(self, epoch: int) -> None:\\n        if hasattr(self._data_provider.sampler, \\\"set_epoch\\\"):\\n            self._data_provider.sampler.set_epoch(epoch)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    \\\"\\\"\\\"\\n    python -m llamafactory.v1.core.utils.batching \\\\\\n        --model llamafactory/tiny-random-qwen2.5 \\\\\\n        --train_dataset data/v1_sft_demo.yaml \\\\\\n        --micro_batch_size 2 \\\\\\n        --global_batch_size 4 \\\\\\n        --batching_workers 0\\n    \\\"\\\"\\\"\\n    from ...config.arg_parser import get_args\\n    from ..data_engine import DataEngine\\n    from ..model_engine import ModelEngine\\n\\n    model_args, data_args, training_args, _ = get_args()\\n    data_engine = DataEngine(data_args.train_dataset)\\n    model_engine = ModelEngine(model_args=model_args)\\n    batch_generator = BatchGenerator(\\n        data_engine,\\n        model_engine.renderer,\\n        micro_batch_size=training_args.micro_batch_size,\\n        global_batch_size=training_args.global_batch_size,\\n        cutoff_len=training_args.cutoff_len,\\n        batching_workers=training_args.batching_workers,\\n        batching_strategy=training_args.batching_strategy,\\n    )\\n    for batch in batch_generator:\\n        print(batch)\\n        print(len(batch))\\n        print(batch[0][\\\"input_ids\\\"].shape)\\n        break\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/utils/callback.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/utils/checkpoint.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3b15e7bda28b6d1f4d87fbbadfec0d74ec73df01272eac5d6c44d013b981e33e\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Checkpoint utilities: low-level helpers and full training save/resume orchestration.\\\"\\\"\\\"\\n\\nimport glob\\nimport json\\nimport os\\nimport random\\nimport shutil\\nfrom typing import Any\\n\\nimport numpy as np\\nimport torch\\nfrom safetensors.torch import load_file\\n\\nfrom ...accelerator.helper import DeviceType, get_current_accelerator\\nfrom ...accelerator.interface import DistributedInterface\\nfrom ...utils import logging\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\nCHECKPOINT_COMPLETE_MARKER = \\\"CHECKPOINT_COMPLETE\\\"\\n\\n\\ndef _parse_checkpoint_step(path: str) -> int:\\n    \\\"\\\"\\\"Extract the step number from a checkpoint directory name, or -1 if invalid.\\\"\\\"\\\"\\n    try:\\n        return int(os.path.basename(path).split(\\\"-\\\")[-1])\\n    except ValueError:\\n        return -1\\n\\n\\ndef find_latest_checkpoint(output_dir: str) -> str | None:\\n    \\\"\\\"\\\"Find the latest valid checkpoint directory in output_dir.\\\"\\\"\\\"\\n    pattern = os.path.join(output_dir, \\\"checkpoint-*\\\")\\n    ckpt_dirs = [d for d in glob.glob(pattern) if _parse_checkpoint_step(d) >= 0]\\n    ckpt_dirs.sort(key=_parse_checkpoint_step)\\n    for d in reversed(ckpt_dirs):\\n        if os.path.exists(os.path.join(d, CHECKPOINT_COMPLETE_MARKER)):\\n            return d\\n    return None\\n\\n\\ndef rotate_checkpoints(output_dir: str, limit: int) -> None:\\n    \\\"\\\"\\\"Keep only the latest `limit` complete checkpoints, delete older ones and incomplete leftovers.\\\"\\\"\\\"\\n    pattern = os.path.join(output_dir, \\\"checkpoint-*\\\")\\n    all_dirs = [d for d in glob.glob(pattern) if _parse_checkpoint_step(d) >= 0]\\n    all_dirs.sort(key=_parse_checkpoint_step)\\n\\n    complete_dirs = []\\n    for d in all_dirs:\\n        if os.path.exists(os.path.join(d, CHECKPOINT_COMPLETE_MARKER)):\\n            complete_dirs.append(d)\\n        else:\\n            shutil.rmtree(d)\\n            logger.info_rank0(f\\\"Cleaned up incomplete checkpoint: {d}\\\")\\n\\n    while len(complete_dirs) > limit:\\n        oldest = complete_dirs.pop(0)\\n        shutil.rmtree(oldest)\\n        logger.info_rank0(f\\\"Deleted old checkpoint: {oldest}\\\")\\n\\n\\ndef save_metadata(ckpt_dir: str, **kwargs) -> None:\\n    \\\"\\\"\\\"Save training metadata as JSON (rank 0 only).\\\"\\\"\\\"\\n    with open(os.path.join(ckpt_dir, \\\"metadata.json\\\"), \\\"w\\\") as f:\\n        json.dump(kwargs, f, indent=2)\\n\\n\\ndef load_metadata(ckpt_dir: str) -> dict:\\n    \\\"\\\"\\\"Load training metadata from a checkpoint directory.\\\"\\\"\\\"\\n    with open(os.path.join(ckpt_dir, \\\"metadata.json\\\")) as f:\\n        return json.load(f)\\n\\n\\ndef _get_accelerator_rng_state():\\n    \\\"\\\"\\\"Get RNG state for the current accelerator, device-agnostic.\\\"\\\"\\\"\\n    device_type = get_current_accelerator().type\\n    if device_type == DeviceType.CUDA:\\n        return torch.cuda.get_rng_state_all()\\n    elif device_type == DeviceType.NPU:\\n        return torch.npu.get_rng_state_all()\\n    elif device_type == DeviceType.XPU:\\n        return torch.xpu.get_rng_state_all()\\n    return None\\n\\n\\ndef _set_accelerator_rng_state(state) -> None:\\n    \\\"\\\"\\\"Set RNG state for the current accelerator, device-agnostic.\\\"\\\"\\\"\\n    if state is None:\\n        return\\n\\n    device_type = get_current_accelerator().type\\n    if device_type == DeviceType.CUDA:\\n        torch.cuda.set_rng_state_all(state)\\n    elif device_type == DeviceType.NPU:\\n        torch.npu.set_rng_state_all(state)\\n    elif device_type == DeviceType.XPU:\\n        torch.xpu.set_rng_state_all(state)\\n\\n\\ndef save_rng_state(ckpt_dir: str, rank: int) -> None:\\n    \\\"\\\"\\\"Save per-rank RNG states for reproducibility.\\\"\\\"\\\"\\n    rng_state = {\\n        \\\"python\\\": random.getstate(),\\n        \\\"numpy\\\": np.random.get_state(),\\n        \\\"torch\\\": torch.random.get_rng_state(),\\n        \\\"accelerator\\\": _get_accelerator_rng_state(),\\n    }\\n    rng_dir = os.path.join(ckpt_dir, \\\"rng_state\\\")\\n    os.makedirs(rng_dir, exist_ok=True)\\n    torch.save(rng_state, os.path.join(rng_dir, f\\\"rank_{rank}.pt\\\"))\\n\\n\\ndef load_rng_state(ckpt_dir: str, rank: int) -> None:\\n    \\\"\\\"\\\"Restore per-rank RNG states from a checkpoint.\\\"\\\"\\\"\\n    path = os.path.join(ckpt_dir, \\\"rng_state\\\", f\\\"rank_{rank}.pt\\\")\\n\\n    if not os.path.exists(path):\\n        logger.warning_rank0(f\\\"RNG state file not found at {path}. Skipping RNG state restoration.\\\")\\n        return\\n\\n    rng_state = torch.load(path, map_location=\\\"cpu\\\", weights_only=False)\\n    random.setstate(rng_state[\\\"python\\\"])\\n    np.random.set_state(rng_state[\\\"numpy\\\"])\\n    torch.random.set_rng_state(rng_state[\\\"torch\\\"])\\n    _set_accelerator_rng_state(rng_state.get(\\\"accelerator\\\"))\\n\\n\\ndef mark_checkpoint_complete(ckpt_dir: str) -> None:\\n    \\\"\\\"\\\"Write a marker file indicating the checkpoint is fully saved.\\\"\\\"\\\"\\n    open(os.path.join(ckpt_dir, CHECKPOINT_COMPLETE_MARKER), \\\"w\\\").close()\\n\\n\\ndef resolve_resume_checkpoint_path(ckpt_path: str, output_dir: str) -> str | None:\\n    \\\"\\\"\\\"Resolve 'auto' to the latest valid checkpoint, or return the path as-is.\\\"\\\"\\\"\\n    if ckpt_path == \\\"auto\\\":\\n        resolved = find_latest_checkpoint(output_dir)\\n        if resolved is None:\\n            logger.warning_rank0(\\n                \\\"resume_from_checkpoint='auto' but no valid checkpoint found in \\\"\\n                f\\\"'{output_dir}'. Training from scratch.\\\"\\n            )\\n        else:\\n            logger.info_rank0(f\\\"Auto-detected latest checkpoint: {resolved}\\\")\\n        return resolved\\n    return ckpt_path\\n\\n\\ndef _save_standard_training_states(\\n    ckpt_dir: str,\\n    model: Any,\\n    optimizer: torch.optim.Optimizer,\\n    processor: Any,\\n    save_ckpt_as_hf: bool,\\n) -> None:\\n    \\\"\\\"\\\"Save model and optimizer for DDP / single-GPU via save_pretrained.\\\"\\\"\\\"\\n    rank = DistributedInterface().get_rank()\\n    if rank == 0:\\n        model_to_save = model.module if hasattr(model, \\\"module\\\") else model\\n        model_dir = os.path.join(ckpt_dir, \\\"model\\\")\\n        model_to_save.save_pretrained(model_dir, state_dict=model_to_save.state_dict(), max_shard_size=\\\"4GB\\\")\\n        processor.save_pretrained(model_dir)\\n\\n        os.makedirs(os.path.join(ckpt_dir, \\\"optimizer\\\"), exist_ok=True)\\n        torch.save(optimizer.state_dict(), os.path.join(ckpt_dir, \\\"optimizer\\\", \\\"state_dict.pt\\\"))\\n\\n        if save_ckpt_as_hf:\\n            logger.info(\\\"Standard saving already uses HF format. No additional 'hf_model' directory created.\\\")\\n\\n\\ndef _load_standard_training_states(\\n    ckpt_dir: str,\\n    model: Any,\\n    optimizer: torch.optim.Optimizer,\\n    map_location: torch.device,\\n) -> None:\\n    \\\"\\\"\\\"Load model and optimizer for DDP / single-GPU.\\\"\\\"\\\"\\n    model_dir = os.path.join(ckpt_dir, \\\"model\\\")\\n    model_to_load = model.module if hasattr(model, \\\"module\\\") else model\\n\\n    is_adapter_ckpt = os.path.exists(os.path.join(model_dir, \\\"adapter_config.json\\\"))\\n\\n    if is_adapter_ckpt:\\n        from peft import set_peft_model_state_dict\\n\\n        adapter_file = os.path.join(model_dir, \\\"adapter_model.safetensors\\\")\\n        if not os.path.exists(adapter_file):\\n            adapter_file = os.path.join(model_dir, \\\"adapter_model.bin\\\")\\n            adapter_state = torch.load(adapter_file, map_location=\\\"cpu\\\", weights_only=True)\\n        else:\\n            adapter_state = load_file(adapter_file, device=\\\"cpu\\\")\\n        set_peft_model_state_dict(model_to_load, adapter_state)\\n    else:\\n        state_dict = {}\\n        for f in sorted(glob.glob(os.path.join(model_dir, \\\"*.safetensors\\\"))):\\n            state_dict.update(load_file(f, device=\\\"cpu\\\"))\\n        if not state_dict:\\n            for f in sorted(glob.glob(os.path.join(model_dir, \\\"*.bin\\\"))):\\n                state_dict.update(torch.load(f, map_location=\\\"cpu\\\", weights_only=True))\\n        if state_dict:\\n            incompatible_keys = model_to_load.load_state_dict(state_dict, strict=False)\\n            if incompatible_keys.missing_keys:\\n                raise RuntimeError(\\n                    f\\\"Unexpected missing keys when loading checkpoint model weights: {incompatible_keys.missing_keys}.\\\"\\n                )\\n        else:\\n            logger.warning_rank0(f\\\"No model weights found in {model_dir}, skipping model state restore.\\\")\\n\\n    optim_path = os.path.join(ckpt_dir, \\\"optimizer\\\", \\\"state_dict.pt\\\")\\n    if os.path.exists(optim_path):\\n        optimizer.load_state_dict(torch.load(optim_path, map_location=map_location, weights_only=True))\\n\\n\\nclass TrainingCheckpointCoordinator:\\n    \\\"\\\"\\\"Coordinates full checkpoint save/resume for a trainer instance.\\\"\\\"\\\"\\n\\n    def __init__(self, trainer: Any) -> None:\\n        self._t = trainer\\n\\n    @property\\n    def _dist_name(self) -> str | None:\\n        return self._t.args.dist_config.name if self._t.args.dist_config is not None else None\\n\\n    def save(self, epoch: int) -> None:\\n        \\\"\\\"\\\"Save a full training checkpoint at the current global step.\\\"\\\"\\\"\\n        ckpt_dir = os.path.join(self._t.args.output_dir, f\\\"checkpoint-{self._t.global_step}\\\")\\n        os.makedirs(ckpt_dir, exist_ok=True)\\n\\n        rank = DistributedInterface().get_rank()\\n\\n        if rank == 0:\\n            save_metadata(\\n                ckpt_dir,\\n                global_step=self._t.global_step,\\n                epoch=epoch,\\n                num_training_steps=self._t.num_training_steps,\\n            )\\n\\n        if self._dist_name in (\\\"fsdp2\\\", \\\"fsdpturbo\\\", \\\"deepspeed\\\"):\\n            from ...plugins.trainer_plugins.distributed.interface import DistributedPlugin\\n\\n            DistributedPlugin(self._dist_name).save_checkpoint(\\n                self._t.model,\\n                self._t.optimizer,\\n                ckpt_dir,\\n                save_ckpt_as_hf=self._t.args.save_ckpt_as_hf,\\n                processor=self._t.renderer.processor,\\n            )\\n        else:\\n            _save_standard_training_states(\\n                ckpt_dir,\\n                self._t.model,\\n                self._t.optimizer,\\n                self._t.renderer.processor,\\n                self._t.args.save_ckpt_as_hf,\\n            )\\n\\n        if self._dist_name != \\\"deepspeed\\\" and rank == 0:\\n            torch.save(self._t.lr_scheduler.state_dict(), os.path.join(ckpt_dir, \\\"scheduler.pt\\\"))\\n\\n        dl_dir = os.path.join(ckpt_dir, \\\"dataloader\\\")\\n        os.makedirs(dl_dir, exist_ok=True)\\n        torch.save(\\n            self._t.train_batch_generator.state_dict(),\\n            os.path.join(dl_dir, f\\\"rank_{rank}.pt\\\"),\\n        )\\n\\n        if self._dist_name != \\\"deepspeed\\\":\\n            save_rng_state(ckpt_dir, rank)\\n\\n        DistributedInterface().sync()\\n\\n        if rank == 0:\\n            mark_checkpoint_complete(ckpt_dir)\\n            if self._t.args.save_total_limit is not None:\\n                rotate_checkpoints(self._t.args.output_dir, self._t.args.save_total_limit)\\n\\n        logger.info_rank0(f\\\"Checkpoint saved to {ckpt_dir}\\\")\\n\\n    def resume(self, ckpt_path: str) -> None:\\n        \\\"\\\"\\\"Restore full training state from a checkpoint directory.\\\"\\\"\\\"\\n        ckpt_dir = resolve_resume_checkpoint_path(ckpt_path, self._t.args.output_dir)\\n        if ckpt_dir is None:\\n            return\\n\\n        if not os.path.isdir(ckpt_dir):\\n            raise ValueError(f\\\"Checkpoint directory does not exist: {ckpt_dir}\\\")\\n\\n        rank = DistributedInterface().get_rank()\\n\\n        metadata = load_metadata(ckpt_dir)\\n        self._t.global_step = metadata[\\\"global_step\\\"]\\n        self._t._resume_epoch = metadata[\\\"epoch\\\"]\\n\\n        if self._dist_name in (\\\"fsdp2\\\", \\\"fsdpturbo\\\", \\\"deepspeed\\\"):\\n            from ...plugins.trainer_plugins.distributed.interface import DistributedPlugin\\n\\n            DistributedPlugin(self._dist_name).load_checkpoint(\\n                self._t.model,\\n                self._t.optimizer,\\n                ckpt_dir,\\n                processor=self._t.renderer.processor,\\n            )\\n        else:\\n            _load_standard_training_states(\\n                ckpt_dir,\\n                self._t.model,\\n                self._t.optimizer,\\n                self._t.device,\\n            )\\n\\n        if self._dist_name != \\\"deepspeed\\\":\\n            sched_path = os.path.join(ckpt_dir, \\\"scheduler.pt\\\")\\n            if os.path.exists(sched_path):\\n                self._t.lr_scheduler.load_state_dict(torch.load(sched_path, map_location=\\\"cpu\\\", weights_only=True))\\n\\n        dl_path = os.path.join(ckpt_dir, \\\"dataloader\\\", f\\\"rank_{rank}.pt\\\")\\n\\n        if os.path.exists(dl_path):\\n            self._t.train_batch_generator.load_state_dict(torch.load(dl_path, map_location=\\\"cpu\\\", weights_only=False))\\n        else:\\n            logger.warning_rank0(\\n                f\\\"Dataloader state file not found at {dl_path}. Skipping Dataloader state restoration.\\\"\\n            )\\n\\n        if self._dist_name != \\\"deepspeed\\\":\\n            load_rng_state(ckpt_dir, rank)\\n\\n        logger.info_rank0(f\\\"Resumed from checkpoint: step={self._t.global_step}, epoch={self._t._resume_epoch}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/utils/collation.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3e9cf146ef35c8b38367b17fe25bac5e33d0cf296e2f1e21e00703d8385102fb\",\"content\":\"# Copyright 2026 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Batch collation utils: padding/truncation and multimodal-feature alignment.\\n\\nThese operate on already-rendered ``ModelInput`` dicts (token lists + pixel tensors) and produce\\npadded ``BatchInput`` tensors. They are pure batching concerns -- independent of how a sample was\\nrendered -- and are consumed by the batch generators in ``core/utils/batching.py`` and\\n``plugins/trainer_plugins/batching.py``. Kept out of ``rendering.py`` so that file is only about\\nturning messages into a single tokenized sample.\\n\\\"\\\"\\\"\\n\\nimport torch\\n\\nfrom ...utils.constants import IGNORE_INDEX\\nfrom ...utils.types import BatchInput, ModelInput, Tensor\\n\\n\\n# Multimodal feature keys the processor emits per sample. They are NOT padded/stacked like text\\n# fields: pixel/audio-feature tensors are ragged (variable patch / frame counts), so the collators\\n# concatenate them along dim 0 instead. Shared by rendering (which copies them verbatim from the\\n# processor) and the collators (which merge them across a micro batch).\\n_MULTIMODAL_PASSTHROUGH_KEYS = frozenset(\\n    {\\n        \\\"pixel_values\\\",\\n        \\\"image_grid_thw\\\",\\n        \\\"pixel_values_videos\\\",\\n        \\\"video_grid_thw\\\",\\n        \\\"second_per_grid_ts\\\",  # Qwen2.5-VL name for the video temporal grid spacing\\n        \\\"video_second_per_grid\\\",  # Qwen2.5-Omni name for the same (fed to get_rope_index)\\n        \\\"input_features\\\",\\n        \\\"feature_attention_mask\\\",\\n    }\\n)\\n\\n\\ndef _pad_and_truncate(tensor: Tensor, max_seqlen: int, pad_value: int = 0) -> Tensor:\\n    if tensor.shape[-1] >= max_seqlen:\\n        return tensor[..., :max_seqlen]\\n\\n    pad_shape = list(tensor.shape)\\n    pad_shape[-1] = max_seqlen - tensor.shape[-1]\\n    pad_tensor = torch.full(pad_shape, pad_value, dtype=tensor.dtype, device=tensor.device)\\n    return torch.cat([tensor, pad_tensor], dim=-1)\\n\\n\\ndef _align_grid_media(\\n    sample: ModelInput,\\n    mm_type_ids: list[int],\\n    max_length: int,\\n    *,\\n    target: int,\\n    grid_key: str,\\n    pixel_key: str,\\n) -> list[int]:\\n    \\\"\\\"\\\"Trim and zero one modality's orphaned tokens for a single sample.\\n\\n    Layout-agnostic: a media item's placeholder tokens may be a single contiguous run or split\\n    into per-frame sub-runs; completeness is decided per token *position*, so both are handled\\n    identically.\\n\\n    Returns the (possibly updated) ``mm_token_type_ids`` so chained calls see earlier zeroing.\\n    \\\"\\\"\\\"\\n    if grid_key not in sample or pixel_key not in sample:\\n        return mm_type_ids\\n\\n    grid = sample[grid_key]\\n    n_items = len(grid)\\n    if n_items == 0:\\n        return mm_type_ids\\n\\n    positions = [i for i, t in enumerate(mm_type_ids) if t == target]\\n    patches_per_item = [int(grid[i].prod()) for i in range(n_items)]\\n    total_patches = sum(patches_per_item)\\n    total_tokens = len(positions)\\n\\n    # merge_size**2 = pixel patches per placeholder token, derived from the data. Bail out\\n    # untouched if the sample is inconsistent.\\n    if total_tokens == 0 or total_patches % total_tokens != 0:\\n        return mm_type_ids\\n    merge_sq = total_patches // total_tokens\\n    tokens_per_item = [p // merge_sq for p in patches_per_item]\\n    if sum(tokens_per_item) != total_tokens:\\n        return mm_type_ids\\n\\n    # Each item owns a contiguous slice of `positions`; it is complete iff its last\\n    # placeholder token lands inside the kept window [0, max_length).\\n    n_complete = 0\\n    cum = 0\\n    for n_i in tokens_per_item:\\n        if positions[cum + n_i - 1] < max_length:\\n            n_complete += 1\\n            cum += n_i\\n        else:\\n            break\\n\\n    if n_complete >= n_items:\\n        return mm_type_ids\\n\\n    # Trim pixel features and grid to the complete prefix.\\n    keep_patches = sum(patches_per_item[:n_complete])\\n    sample[pixel_key] = sample[pixel_key][:keep_patches]\\n    sample[grid_key] = grid[:n_complete]\\n\\n    # Zero out orphaned placeholder tokens that fall inside the kept window; tokens\\n    # beyond max_length are removed by truncation anyway (positions are sorted).\\n    input_ids = list(sample[\\\"input_ids\\\"])\\n    mm_type_ids = list(mm_type_ids)\\n    labels = list(sample[\\\"labels\\\"]) if \\\"labels\\\" in sample else None\\n    loss_weights = list(sample[\\\"loss_weights\\\"]) if \\\"loss_weights\\\" in sample else None\\n\\n    for pos in positions[cum:]:\\n        if pos >= max_length:\\n            break\\n        input_ids[pos] = 0\\n        mm_type_ids[pos] = 0\\n        if labels is not None:\\n            labels[pos] = IGNORE_INDEX\\n        if loss_weights is not None:\\n            loss_weights[pos] = 0.0\\n\\n    sample[\\\"input_ids\\\"] = input_ids\\n    sample[\\\"mm_token_type_ids\\\"] = mm_type_ids\\n    if labels is not None:\\n        sample[\\\"labels\\\"] = labels\\n    if loss_weights is not None:\\n        sample[\\\"loss_weights\\\"] = loss_weights\\n    return mm_type_ids\\n\\n\\ndef _align_audio(sample: ModelInput, mm_type_ids: list[int], max_length: int, *, target: int = 3) -> list[int]:\\n    \\\"\\\"\\\"Trim and zero orphaned audio tokens for a single sample on truncation.\\n\\n    Returns the (possibly updated) ``mm_token_type_ids``.\\n    \\\"\\\"\\\"\\n    if \\\"input_features\\\" not in sample or \\\"feature_attention_mask\\\" not in sample:\\n        return mm_type_ids\\n\\n    n_items = sample[\\\"input_features\\\"].shape[0]\\n    if n_items == 0:\\n        return mm_type_ids\\n\\n    positions = [i for i, t in enumerate(mm_type_ids) if t == target]\\n    if not positions:\\n        return mm_type_ids\\n\\n    # Group the marked positions into maximal contiguous runs; each run is one audio's token span.\\n    runs: list[tuple[int, int]] = []\\n    run_start = prev = positions[0]\\n    for pos in positions[1:]:\\n        if pos != prev + 1:\\n            runs.append((run_start, prev))\\n            run_start = pos\\n        prev = pos\\n    runs.append((run_start, prev))\\n\\n    # Layout must match the feature rows one-to-one, else bail rather than corrupt the mapping.\\n    if len(runs) != n_items:\\n        return mm_type_ids\\n\\n    # An audio is complete iff its last placeholder token lands inside the kept window.\\n    n_complete = 0\\n    for _start, end in runs:\\n        if end < max_length:\\n            n_complete += 1\\n        else:\\n            break\\n\\n    if n_complete >= n_items:\\n        return mm_type_ids\\n\\n    # Trim feature rows to the complete prefix.\\n    sample[\\\"input_features\\\"] = sample[\\\"input_features\\\"][:n_complete]\\n    sample[\\\"feature_attention_mask\\\"] = sample[\\\"feature_attention_mask\\\"][:n_complete]\\n\\n    # Zero out orphaned placeholder tokens that fall inside the kept window; tokens beyond\\n    # max_length are removed by truncation anyway.\\n    input_ids = list(sample[\\\"input_ids\\\"])\\n    mm_type_ids = list(mm_type_ids)\\n    labels = list(sample[\\\"labels\\\"]) if \\\"labels\\\" in sample else None\\n    loss_weights = list(sample[\\\"loss_weights\\\"]) if \\\"loss_weights\\\" in sample else None\\n\\n    for start, end in runs[n_complete:]:\\n        for pos in range(start, end + 1):\\n            if pos >= max_length:\\n                break\\n            input_ids[pos] = 0\\n            mm_type_ids[pos] = 0\\n            if labels is not None:\\n                labels[pos] = IGNORE_INDEX\\n            if loss_weights is not None:\\n                loss_weights[pos] = 0.0\\n\\n    sample[\\\"input_ids\\\"] = input_ids\\n    sample[\\\"mm_token_type_ids\\\"] = mm_type_ids\\n    if labels is not None:\\n        sample[\\\"labels\\\"] = labels\\n    if loss_weights is not None:\\n        sample[\\\"loss_weights\\\"] = loss_weights\\n    return mm_type_ids\\n\\n\\ndef _align_multimodal_on_truncation(sample: ModelInput, max_length: int) -> ModelInput:\\n    \\\"\\\"\\\"Remove orphaned multimodal data when the sequence will be truncated.\\n\\n    When cutoff_len truncates input_ids, media whose placeholder tokens are partially cut lose\\n    their token<->feature correspondence. Trims pixel_values/grid_thw (vision) and\\n    input_features/feature_attention_mask (audio) to the complete items and zeros out orphaned\\n    placeholder tokens so the model ignores them.\\n    \\\"\\\"\\\"\\n    mm_type_ids = sample.get(\\\"mm_token_type_ids\\\")\\n    if mm_type_ids is None:\\n        return sample\\n\\n    sample = dict(sample)\\n\\n    mm_type_ids = _align_grid_media(\\n        sample, mm_type_ids, max_length, target=1, grid_key=\\\"image_grid_thw\\\", pixel_key=\\\"pixel_values\\\"\\n    )\\n    mm_type_ids = _align_grid_media(\\n        sample, mm_type_ids, max_length, target=2, grid_key=\\\"video_grid_thw\\\", pixel_key=\\\"pixel_values_videos\\\"\\n    )\\n    mm_type_ids = _align_audio(sample, mm_type_ids, max_length, target=3)\\n\\n    # Remove empty multimodal fields entirely\\n    if \\\"image_grid_thw\\\" in sample and len(sample[\\\"image_grid_thw\\\"]) == 0:\\n        del sample[\\\"pixel_values\\\"]\\n        del sample[\\\"image_grid_thw\\\"]\\n    if \\\"video_grid_thw\\\" in sample and len(sample[\\\"video_grid_thw\\\"]) == 0:\\n        del sample[\\\"pixel_values_videos\\\"]\\n        del sample[\\\"video_grid_thw\\\"]\\n    if \\\"input_features\\\" in sample and sample[\\\"input_features\\\"].shape[0] == 0:\\n        del sample[\\\"input_features\\\"]\\n        del sample[\\\"feature_attention_mask\\\"]\\n\\n    return sample\\n\\n\\ndef pad_and_truncate(samples: list[ModelInput], max_seqlen: int) -> list[BatchInput]:\\n    max_length = min(max(len(sample[\\\"input_ids\\\"]) for sample in samples), max_seqlen)\\n    padded_samples = []\\n    for sample in samples:\\n        # Align multimodal fields before truncation: remove images/videos whose\\n        # placeholder tokens would be partially cut, preventing pixel<->token mismatch.\\n        if len(sample[\\\"input_ids\\\"]) > max_length and any(k in sample for k in _MULTIMODAL_PASSTHROUGH_KEYS):\\n            sample = _align_multimodal_on_truncation(sample, max_length)\\n\\n        padded_sample = {}\\n        for key, value in sample.items():\\n            if key in _MULTIMODAL_PASSTHROUGH_KEYS:\\n                padded_sample[key] = value\\n                continue\\n\\n            if \\\"label\\\" in key:\\n                pad_value = IGNORE_INDEX\\n            else:\\n                pad_value = 0\\n\\n            if not isinstance(value, str):\\n                padded_sample[key] = _pad_and_truncate(torch.tensor(value), max_length, pad_value)\\n            else:\\n                padded_sample[key] = value\\n\\n        padded_samples.append(padded_sample)\\n\\n    return padded_samples\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/utils/inference_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eda5f1f0e8a3bee455fd2d8394c47d9f7dc247ccd2e95b0e97f8842f0c1a86ce\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport asyncio\\nimport os\\nfrom abc import ABC, abstractmethod\\nfrom collections.abc import AsyncGenerator\\nfrom threading import Thread\\n\\nimport torch\\nfrom transformers import AsyncTextIteratorStreamer\\n\\nfrom ...accelerator.interface import DistributedInterface\\nfrom ...config import ModelArguments, SampleArguments\\nfrom ...utils.helper import get_tokenizer\\nfrom ...utils.types import HFModel, Message, Sample, TorchDataset\\nfrom ..rendering import Renderer\\n\\n\\nclass BaseEngine(ABC):\\n    @abstractmethod\\n    def __init__(\\n        self,\\n        args: SampleArguments,\\n        model_args: ModelArguments,\\n        model: HFModel,\\n        renderer: Renderer,\\n    ) -> None:\\n        \\\"\\\"\\\"Initialize the engine.\\n\\n        Args:\\n            args: Sample arguments.\\n            model_args: Model arguments.\\n            model: Model.\\n            renderer: Renderer.\\n        \\\"\\\"\\\"\\n        ...\\n\\n    @abstractmethod\\n    async def generate(self, messages: list[Message], tools: str | None = None) -> AsyncGenerator[str, None]:\\n        \\\"\\\"\\\"Generate tokens asynchronously.\\n\\n        Args:\\n            messages: List of messages.\\n            tools: Tools string.\\n\\n        Yields:\\n            Generated tokens.\\n        \\\"\\\"\\\"\\n        ...\\n\\n    @abstractmethod\\n    async def batch_infer(self, dataset: TorchDataset) -> list[Sample]:\\n        \\\"\\\"\\\"Batch infer samples.\\n\\n        Args:\\n            dataset: Torch dataset.\\n\\n        Returns:\\n            List of samples.\\n        \\\"\\\"\\\"\\n        ...\\n\\n\\nclass HuggingFaceEngine(BaseEngine):\\n    def __init__(\\n        self,\\n        args: SampleArguments,\\n        model_args: ModelArguments,\\n        model: HFModel,\\n        renderer: Renderer,\\n    ) -> None:\\n        self.args = args\\n        self.model_args = model_args\\n        self.model = model\\n        self.renderer = renderer\\n        self.semaphore = asyncio.Semaphore(int(os.getenv(\\\"MAX_CONCURRENT\\\", \\\"1\\\")))\\n\\n    @torch.inference_mode()\\n    async def generate(self, messages: list[Message], tools: str | None = None) -> AsyncGenerator[str, None]:\\n        async with self.semaphore:\\n            model_inputs = self.renderer.render_messages(messages, tools, is_generate=True)\\n            streamer = AsyncTextIteratorStreamer(\\n                tokenizer=get_tokenizer(self.renderer.processor),\\n                skip_prompt=True,\\n                skip_special_tokens=True,  # TODO: configurable\\n            )\\n            device = DistributedInterface().current_device\\n            kwargs = {\\n                \\\"input_ids\\\": torch.tensor([model_inputs[\\\"input_ids\\\"]]).to(device),\\n                \\\"attention_mask\\\": torch.tensor([model_inputs[\\\"attention_mask\\\"]]).to(device),\\n                \\\"max_new_tokens\\\": self.args.max_new_tokens,\\n                \\\"streamer\\\": streamer,\\n            }\\n            thread = Thread(target=self.model.generate, kwargs=kwargs, daemon=True)\\n            thread.start()\\n\\n            async for token in streamer:\\n                yield token\\n\\n    async def batch_infer(self, dataset: TorchDataset) -> list[Sample]:\\n        \\\"\\\"\\\"Batch infer samples.\\n\\n        Args:\\n            dataset: Torch dataset.\\n\\n        Returns:\\n            List of samples.\\n        \\\"\\\"\\\"\\n        raise NotImplementedError(\\\"Batch infer is not implemented.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/launcher.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ef8b225d7dfa8c55db98bcaab9b698db069518b379fb5d84abe6c7a5c94f442d\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nimport subprocess\\nimport sys\\nfrom copy import deepcopy\\n\\n\\nUSAGE = (\\n    \\\"-\\\" * 70\\n    + \\\"\\\\n\\\"\\n    + \\\"| Usage:                                                             |\\\\n\\\"\\n    + \\\"|   llamafactory-cli sft -h: train models                            |\\\\n\\\"\\n    + \\\"|   llamafactory-cli version: show version info                      |\\\\n\\\"\\n    + \\\"| Hint: You can use `lmf` as a shortcut for `llamafactory-cli`.      |\\\\n\\\"\\n    + \\\"-\\\" * 70\\n)\\n\\n_DIST_TRAIN_COMMANDS = (\\\"train\\\", \\\"sft\\\", \\\"dpo\\\", \\\"rm\\\")\\n\\n\\ndef launch():\\n    from .accelerator.helper import get_device_count\\n    from .utils.env import find_available_port, is_env_enabled, use_kt, use_ray\\n    from .utils.logging import get_logger\\n\\n    logger = get_logger(__name__)\\n\\n    # NOTE:\\n    # `llamafactory-cli <command> ...` enters here first.\\n    # We may re-launch via `torchrun` for distributed training. In that case we must\\n    # forward `<command>` as argv[1] to the re-executed script, otherwise the script\\n    # will misinterpret the first user argument (e.g. yaml config) as the command.\\n    command = sys.argv.pop(1) if len(sys.argv) > 1 else \\\"help\\\"\\n\\n    if command in _DIST_TRAIN_COMMANDS and (\\n        is_env_enabled(\\\"FORCE_TORCHRUN\\\") or (get_device_count() > 1 and not use_ray() and not use_kt())\\n    ):\\n        nnodes = os.getenv(\\\"NNODES\\\", \\\"1\\\")\\n        node_rank = os.getenv(\\\"NODE_RANK\\\", \\\"0\\\")\\n        nproc_per_node = os.getenv(\\\"NPROC_PER_NODE\\\", str(get_device_count()))\\n        master_addr = os.getenv(\\\"MASTER_ADDR\\\", \\\"127.0.0.1\\\")\\n        master_port = os.getenv(\\\"MASTER_PORT\\\", str(find_available_port()))\\n        logger.info_rank0(f\\\"Initializing {nproc_per_node} distributed tasks at: {master_addr}:{master_port}\\\")\\n        if int(nnodes) > 1:\\n            logger.info_rank0(f\\\"Multi-node training enabled: num nodes: {nnodes}, node rank: {node_rank}\\\")\\n\\n        # elastic launch support\\n        max_restarts = os.getenv(\\\"MAX_RESTARTS\\\", \\\"0\\\")\\n        rdzv_id = os.getenv(\\\"RDZV_ID\\\")\\n        min_nnodes = os.getenv(\\\"MIN_NNODES\\\")\\n        max_nnodes = os.getenv(\\\"MAX_NNODES\\\")\\n\\n        env = deepcopy(os.environ)\\n        if is_env_enabled(\\\"OPTIM_TORCH\\\", \\\"1\\\"):\\n            # optimize DDP, see https://zhuanlan.zhihu.com/p/671834539\\n            env[\\\"PYTORCH_CUDA_ALLOC_CONF\\\"] = \\\"expandable_segments:True\\\"\\n            env[\\\"TORCH_NCCL_AVOID_RECORD_STREAMS\\\"] = \\\"1\\\"\\n\\n        torchrun_args = [\\n            \\\"torchrun\\\",\\n            \\\"--nproc-per-node\\\",\\n            nproc_per_node,\\n        ]\\n        if rdzv_id is not None:\\n            # launch elastic job with fault tolerant support when possible\\n            # see also https://docs.pytorch.org/docs/stable/elastic/train_script.html\\n            rdzv_nnodes = nnodes\\n            # elastic number of nodes if MIN_NNODES and MAX_NNODES are set\\n            if min_nnodes is not None and max_nnodes is not None:\\n                rdzv_nnodes = f\\\"{min_nnodes}:{max_nnodes}\\\"\\n\\n            torchrun_args.extend(\\n                [\\n                    \\\"--nnodes\\\",\\n                    rdzv_nnodes,\\n                    \\\"--rdzv-id\\\",\\n                    rdzv_id,\\n                    \\\"--rdzv-backend\\\",\\n                    \\\"c10d\\\",\\n                    \\\"--rdzv-endpoint\\\",\\n                    f\\\"{master_addr}:{master_port}\\\",\\n                    \\\"--max-restarts\\\",\\n                    max_restarts,\\n                ]\\n            )\\n        else:\\n            # NOTE: DO NOT USE shell=True to avoid security risk\\n            torchrun_args.extend(\\n                [\\n                    \\\"--nnodes\\\",\\n                    nnodes,\\n                    \\\"--node_rank\\\",\\n                    node_rank,\\n                    \\\"--master_addr\\\",\\n                    master_addr,\\n                    \\\"--master_port\\\",\\n                    master_port,\\n                ]\\n            )\\n\\n        script_args = [__file__, command] + sys.argv[1:]\\n        process = subprocess.run(\\n            torchrun_args + script_args,\\n            env=env,\\n            check=True,\\n        )\\n\\n        sys.exit(process.returncode)\\n\\n    elif command == \\\"chat\\\":\\n        from .samplers.cli_sampler import run_chat\\n\\n        run_chat()\\n\\n    elif command == \\\"merge\\\":\\n        from llamafactory.v1.plugins.model_plugins.peft import merge_and_export_model\\n\\n        merge_and_export_model()\\n\\n    elif command == \\\"env\\\":\\n        raise NotImplementedError(\\\"Environment information is not implemented yet.\\\")\\n\\n    elif command == \\\"version\\\":\\n        raise NotImplementedError(\\\"Version information is not implemented yet.\\\")\\n\\n    elif command == \\\"help\\\":\\n        print(USAGE)\\n\\n    elif command in _DIST_TRAIN_COMMANDS:\\n        # Single GPU training without torchrun\\n        if command in (\\\"train\\\", \\\"sft\\\"):\\n            from llamafactory.v1.trainers.sft_trainer import run_sft\\n\\n            run_sft()\\n        elif command == \\\"dpo\\\":\\n            from llamafactory.v1.trainers.dpo_trainer import run_dpo\\n\\n            run_dpo()\\n        elif command == \\\"rm\\\":\\n            from llamafactory.v1.trainers.rm_trainer import run_rm\\n\\n            run_rm()\\n\\n    else:\\n        print(f\\\"Unknown command: {command}.\\\\n{USAGE}\\\")\\n\\n\\ndef main():\\n    # sys.argv[1] contains the command (sft/dpo/rm/train), sys.argv[2:] contains the rest args\\n    command = sys.argv[1] if len(sys.argv) > 1 else \\\"sft\\\"\\n\\n    # Routing needs the sub-command, but downstream trainers usually expect argv without it.\\n    if command in _DIST_TRAIN_COMMANDS:\\n        sys.argv.pop(1)\\n    else:\\n        # Backward-compat: if someone runs `torchrun launcher.py config.yaml`,\\n        # treat it as sft by default.\\n        if len(sys.argv) > 1 and sys.argv[1].endswith((\\\".yaml\\\", \\\".yml\\\")):\\n            command = \\\"sft\\\"\\n    if command in (\\\"train\\\", \\\"sft\\\"):\\n        from llamafactory.v1.trainers.sft_trainer import run_sft\\n\\n        run_sft()\\n    elif command == \\\"dpo\\\":\\n        from llamafactory.v1.trainers.dpo_trainer import run_dpo\\n\\n        run_dpo()\\n    elif command == \\\"rm\\\":\\n        from llamafactory.v1.trainers.rm_trainer import run_rm\\n\\n        run_rm()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/data_plugins/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/data_plugins/converter.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"036eca2eaaf0e9e883f3750ba51c1f7206377a7b7d57e25ee732ffff57c518b5\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nimport json\\nimport re\\nfrom typing import Any, Literal, NotRequired, TypedDict\\n\\nfrom ...utils import logging\\nfrom ...utils.constants import AUDIO_PLACEHOLDER, IMAGE_PLACEHOLDER, VIDEO_PLACEHOLDER\\nfrom ...utils.plugin import BasePlugin\\nfrom ...utils.types import Content, DPOSample, Sample, SFTSample, ToolCall\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass AlpacaSample(TypedDict, total=False):\\n    system: NotRequired[str]\\n    instruction: str\\n    input: NotRequired[str]\\n    output: str\\n    images: NotRequired[list[str] | str]\\n    videos: NotRequired[list[str] | str]\\n    audios: NotRequired[list[str] | str]\\n\\n\\nSharegptMessage = TypedDict(\\n    \\\"SharegptMessage\\\",\\n    {\\\"from\\\": Literal[\\\"human\\\", \\\"gpt\\\", \\\"system\\\", \\\"function_call\\\", \\\"observation\\\"], \\\"value\\\": str},\\n)\\n\\n\\nclass SharegptSample(TypedDict, total=False):\\n    conversations: list[SharegptMessage]\\n    tools: NotRequired[str]\\n    images: NotRequired[list[str] | str]\\n    videos: NotRequired[list[str] | str]\\n    audios: NotRequired[list[str] | str]\\n\\n\\nclass OpenaiMessage(TypedDict, total=False):\\n    role: Literal[\\\"user\\\", \\\"assistant\\\", \\\"tool\\\"]\\n    content: str\\n\\n\\nclass OpenaiSample(TypedDict, total=False):\\n    messages: list[OpenaiMessage]\\n\\n\\nclass PairSample(TypedDict, total=False):\\n    chosen: list[OpenaiMessage]\\n    rejected: list[OpenaiMessage]\\n    images: NotRequired[list[str] | str]\\n    videos: NotRequired[list[str] | str]\\n    audios: NotRequired[list[str] | str]\\n\\n\\n# Inline media tag -> v1 content block type, and the raw-sample column holding the paths.\\n_MEDIA_SPECS: tuple[tuple[str, str, str], ...] = (\\n    (IMAGE_PLACEHOLDER, \\\"image_url\\\", \\\"images\\\"),\\n    (VIDEO_PLACEHOLDER, \\\"video_url\\\", \\\"videos\\\"),\\n    (AUDIO_PLACEHOLDER, \\\"audio_url\\\", \\\"audios\\\"),\\n)\\n_TAG_TO_BLOCK = {tag: block_type for tag, block_type, _col in _MEDIA_SPECS}\\n_TAG_PATTERN = re.compile(\\\"(\\\" + \\\"|\\\".join(re.escape(tag) for tag, _b, _c in _MEDIA_SPECS) + \\\")\\\")\\n\\n\\ndef _as_media_list(value: Any) -> list:\\n    \\\"\\\"\\\"Normalize a media column value into a list of paths/URLs (None -> [], scalar -> [scalar]).\\\"\\\"\\\"\\n    if value is None:\\n        return []\\n    if isinstance(value, (list, tuple)):\\n        return list(value)\\n    return [value]\\n\\n\\ndef _build_media_iters(raw_sample: dict[str, Any]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Build per-modality path iterators from a raw sample's media columns.\\\"\\\"\\\"\\n    return {tag: iter(_as_media_list(raw_sample.get(col))) for tag, _block_type, col in _MEDIA_SPECS}\\n\\n\\ndef _to_content_blocks(text: str, media_iters: dict[str, Any]) -> list[Content]:\\n    \\\"\\\"\\\"Split ``text`` on inline media placeholders, interleaving media-url content blocks.\\n\\n    Each placeholder consumes the next path from its modality iterator (in document order). Plain\\n    text with no placeholders yields a single text block (byte-identical to the legacy behavior).\\n    Raises on an unmatched placeholder (more tags than media files).\\n    \\\"\\\"\\\"\\n    if not _TAG_PATTERN.search(text):\\n        return [{\\\"type\\\": \\\"text\\\", \\\"value\\\": text}]\\n\\n    blocks: list[Content] = []\\n    for segment in _TAG_PATTERN.split(text):\\n        block_type = _TAG_TO_BLOCK.get(segment)\\n        if block_type is not None:\\n            try:\\n                path = next(media_iters[segment])\\n            except StopIteration:\\n                raise ValueError(f\\\"More {segment} tags than provided media files.\\\") from None\\n            blocks.append({\\\"type\\\": block_type, \\\"value\\\": path})\\n        elif segment:\\n            blocks.append({\\\"type\\\": \\\"text\\\", \\\"value\\\": segment})\\n    return blocks\\n\\n\\ndef _assert_media_consumed(media_iters: dict[str, Any]) -> None:\\n    \\\"\\\"\\\"Ensure every media file was referenced by a tag (fewer tags than media -> error).\\\"\\\"\\\"\\n    for tag, media_iter in media_iters.items():\\n        unused = len(list(media_iter))\\n        if unused:\\n            raise ValueError(f\\\"Fewer {tag} tags than provided media files ({unused} unused).\\\")\\n\\n\\nclass DataConverterPlugin(BasePlugin):\\n    \\\"\\\"\\\"Plugin for data converters.\\\"\\\"\\\"\\n\\n    def __call__(self, raw_sample: dict[str, Any]) -> Sample:\\n        return super().__call__(raw_sample)\\n\\n\\n@DataConverterPlugin(\\\"alpaca\\\").register()\\ndef alpaca_converter(raw_sample: AlpacaSample) -> SFTSample:\\n    \\\"\\\"\\\"Convert Alpaca sample to SFT sample.\\n\\n    See raw example at: https://huggingface.co/datasets/llamafactory/alpaca_gpt4_en\\n\\n    Args:\\n        raw_sample (AlpacaSample): Alpaca sample.\\n\\n    Returns:\\n        SFTSample: SFT sample.\\n    \\\"\\\"\\\"\\n    messages = []\\n    media_iters = _build_media_iters(raw_sample)\\n    if \\\"system\\\" in raw_sample:\\n        messages.append(\\n            {\\\"role\\\": \\\"system\\\", \\\"content\\\": [{\\\"type\\\": \\\"text\\\", \\\"value\\\": raw_sample[\\\"system\\\"]}], \\\"loss_weight\\\": 0.0}\\n        )\\n\\n    if \\\"instruction\\\" in raw_sample or \\\"input\\\" in raw_sample:\\n        messages.append(\\n            {\\n                \\\"role\\\": \\\"user\\\",\\n                \\\"content\\\": _to_content_blocks(\\n                    raw_sample.get(\\\"instruction\\\", \\\"\\\") + raw_sample.get(\\\"input\\\", \\\"\\\"), media_iters\\n                ),\\n                \\\"loss_weight\\\": 0.0,\\n            }\\n        )\\n\\n    if \\\"output\\\" in raw_sample:\\n        messages.append(\\n            {\\\"role\\\": \\\"assistant\\\", \\\"content\\\": [{\\\"type\\\": \\\"text\\\", \\\"value\\\": raw_sample[\\\"output\\\"]}], \\\"loss_weight\\\": 1.0}\\n        )\\n\\n    _assert_media_consumed(media_iters)\\n    return {\\\"messages\\\": messages}\\n\\n\\n@DataConverterPlugin(\\\"sharegpt\\\").register()\\ndef sharegpt_converter(raw_sample: SharegptSample) -> SFTSample:\\n    \\\"\\\"\\\"Convert ShareGPT sample to SFT sample.\\n\\n    See raw example at: https://huggingface.co/datasets/llamafactory/glaive_toolcall_en\\n\\n    Args:\\n        raw_sample (SharegptSample): ShareGPT sample.\\n\\n    Returns:\\n        SFTSample: SFT sample.\\n    \\\"\\\"\\\"\\n    tag_mapping = {\\n        \\\"system\\\": \\\"system\\\",\\n        \\\"human\\\": \\\"user\\\",\\n        \\\"gpt\\\": \\\"assistant\\\",\\n        \\\"observation\\\": \\\"tool\\\",\\n        \\\"function_call\\\": \\\"assistant\\\",\\n    }\\n    sample = {}\\n    messages = []\\n    media_iters = _build_media_iters(raw_sample)\\n    for message in raw_sample.get(\\\"conversations\\\", []):\\n        tag = message[\\\"from\\\"]\\n        if tag not in tag_mapping:\\n            logger.warning_rank0(f\\\"Unsupported role tag {tag} in message: {message}\\\")\\n        elif tag == \\\"function_call\\\":\\n            try:\\n                tool_calls: ToolCall | list[ToolCall] = json.loads(message[\\\"value\\\"])\\n            except json.JSONDecodeError:\\n                logger.warning_rank0(f\\\"Invalid tool call format: {str(message['value'])}\\\")\\n                continue\\n\\n            if not isinstance(tool_calls, list):\\n                tool_calls = [tool_calls]\\n\\n            messages.append(\\n                {\\n                    \\\"role\\\": \\\"assistant\\\",\\n                    \\\"content\\\": [{\\\"type\\\": \\\"tool_call\\\", \\\"value\\\": json.dumps(tool_call)} for tool_call in tool_calls],\\n                    \\\"loss_weight\\\": 1.0,\\n                }\\n            )\\n        else:\\n            messages.append(\\n                {\\n                    \\\"role\\\": tag_mapping[tag],\\n                    \\\"content\\\": _to_content_blocks(message[\\\"value\\\"], media_iters),\\n                    \\\"loss_weight\\\": 1.0 if tag == \\\"gpt\\\" else 0.0,\\n                }\\n            )\\n\\n    _assert_media_consumed(media_iters)\\n    sample[\\\"messages\\\"] = messages\\n\\n    tools = raw_sample.get(\\\"tools\\\")\\n    if tools:\\n        try:\\n            tools: list[dict[str, Any]] = json.loads(tools)\\n            sample[\\\"tools\\\"] = json.dumps(tools)\\n        except json.JSONDecodeError:\\n            logger.warning_rank0(f\\\"Invalid tools format: {str(tools)}\\\")\\n\\n    return sample\\n\\n\\n@DataConverterPlugin(\\\"pair\\\").register()\\ndef pair_converter(raw_sample: PairSample) -> DPOSample:\\n    \\\"\\\"\\\"Convert Pair sample to DPO sample.\\n\\n    See raw example at: https://huggingface.co/datasets/HuggingFaceH4/orca_dpo_pairs\\n\\n    Args:\\n        raw_sample (PairSample): pair sample with chosen, rejected fields.\\n\\n    Returns:\\n        DPOSample: DPO sample with chosen_messages and rejected_messages.\\n    \\\"\\\"\\\"\\n\\n    def process_message(raw_messages: list[OpenaiMessage]):\\n        # chosen and rejected share the sample's media; each side consumes its own iterators.\\n        media_iters = _build_media_iters(raw_sample)\\n        messages = []\\n        for message in raw_messages:\\n            if message[\\\"role\\\"] == \\\"tool\\\":\\n                try:\\n                    tool_calls: ToolCall | list[ToolCall] = json.loads(message[\\\"content\\\"])\\n                except json.JSONDecodeError:\\n                    logger.warning_rank0(f\\\"Invalid tool call format: {str(message['content'])}\\\")\\n                    continue\\n\\n                if not isinstance(tool_calls, list):\\n                    tool_calls = [tool_calls]\\n\\n                messages.append(\\n                    {\\n                        \\\"role\\\": message[\\\"role\\\"],\\n                        \\\"content\\\": [{\\\"type\\\": \\\"tool_call\\\", \\\"value\\\": json.dumps(tool_call)} for tool_call in tool_calls],\\n                        \\\"loss_weight\\\": 1.0 if message[\\\"role\\\"] == \\\"assistant\\\" else 0.0,\\n                    }\\n                )\\n            else:\\n                messages.append(\\n                    {\\n                        \\\"role\\\": message[\\\"role\\\"],\\n                        \\\"content\\\": _to_content_blocks(message[\\\"content\\\"], media_iters),\\n                        \\\"loss_weight\\\": 1.0 if message[\\\"role\\\"] == \\\"assistant\\\" else 0.0,\\n                    }\\n                )\\n\\n        _assert_media_consumed(media_iters)\\n        return messages\\n\\n    sample = {}\\n    sample[\\\"chosen_messages\\\"] = process_message(raw_sample.get(\\\"chosen\\\", []))\\n    sample[\\\"rejected_messages\\\"] = process_message(raw_sample.get(\\\"rejected\\\", []))\\n\\n    tools = raw_sample.get(\\\"tools\\\")\\n    if tools:\\n        try:\\n            tools: list[dict[str, Any]] = json.loads(tools)\\n            sample[\\\"tools\\\"] = json.dumps(tools)\\n        except json.JSONDecodeError:\\n            logger.warning_rank0(f\\\"Invalid tools format: {str(tools)}\\\")\\n\\n    return sample\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/data_plugins/loader.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"69ba8632ace5906699b23619d007a951d5c0a819e0c21e623f2136e56ce99fa7\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nimport os\\nimport random\\nfrom typing import Any, Literal\\n\\nfrom datasets import load_dataset\\n\\nfrom ...utils.plugin import BasePlugin\\nfrom ...utils.types import DatasetInfo, HFDataset\\n\\n\\nclass DataLoaderPlugin(BasePlugin):\\n    \\\"\\\"\\\"Plugin for loading dataset.\\\"\\\"\\\"\\n\\n    def load(self, dataset_info: DatasetInfo) -> HFDataset:\\n        path = dataset_info[\\\"path\\\"]\\n        split = dataset_info.get(\\\"split\\\", \\\"train\\\")\\n        streaming = dataset_info.get(\\\"streaming\\\", False)\\n        return super().__call__(path, split, streaming)\\n\\n\\ndef _get_builder_name(path: str) -> Literal[\\\"arrow\\\", \\\"csv\\\", \\\"json\\\", \\\"parquet\\\", \\\"text\\\"]:\\n    \\\"\\\"\\\"Get dataset builder name.\\n\\n    Args:\\n        path (str): Dataset path.\\n\\n    Returns:\\n        Literal[\\\"arrow\\\", \\\"csv\\\", \\\"json\\\", \\\"parquet\\\", \\\"text\\\"]: Dataset builder name.\\n    \\\"\\\"\\\"\\n    filetype = os.path.splitext(path)[-1][1:]\\n    if filetype in [\\\"arrow\\\", \\\"csv\\\", \\\"json\\\", \\\"jsonl\\\", \\\"parquet\\\", \\\"txt\\\"]:\\n        return filetype.replace(\\\"jsonl\\\", \\\"json\\\").replace(\\\"txt\\\", \\\"text\\\")\\n    else:\\n        raise ValueError(f\\\"Unknown dataset filetype: {filetype}.\\\")\\n\\n\\n@DataLoaderPlugin(\\\"local\\\").register()\\ndef load_data_from_file(filepath: str, split: str, streaming: bool) -> HFDataset:\\n    if os.path.isdir(filepath):\\n        filetype = _get_builder_name(os.listdir(filepath)[0])\\n        dataset = load_dataset(filetype, data_dir=filepath, split=split)\\n    elif os.path.isfile(filepath):\\n        filetype = _get_builder_name(filepath)\\n        dataset = load_dataset(filetype, data_files=filepath, split=split)\\n    else:\\n        raise ValueError(f\\\"Can not load dataset from {filepath}.\\\")\\n\\n    if streaming:  # faster when data is streamed from local files\\n        dataset = dataset.to_iterable_dataset()\\n\\n    return dataset\\n\\n\\ndef adjust_data_index(\\n    data_index: list[tuple[str, int]], size: int | None, weight: float | None\\n) -> list[tuple[str, int]]:\\n    \\\"\\\"\\\"Adjust dataset index by size and weight.\\n\\n    Args:\\n        data_index (list[tuple[str, int]]): List of (dataset_name, sample_index).\\n        size (Optional[int]): Desired dataset size.\\n        weight (Optional[float]): Desired dataset weight.\\n\\n    Returns:\\n        list[tuple[str, int]]: Adjusted dataset index.\\n    \\\"\\\"\\\"\\n    if size is not None:\\n        data_index = random.choices(data_index, k=size)\\n\\n    if weight is not None:\\n        data_index = random.choices(data_index, k=int(len(data_index) * weight))\\n\\n    return data_index\\n\\n\\ndef select_data_sample(\\n    data_index: list[tuple[str, int]], index: slice | list[int] | Any\\n) -> tuple[str, int] | list[tuple[str, int]]:\\n    \\\"\\\"\\\"Select dataset samples.\\n\\n    Args:\\n        data_index (list[tuple[str, int]]): List of (dataset_name, sample_index).\\n        index (Union[slice, list[int], Any]): Index of dataset samples.\\n\\n    Returns:\\n        Union[tuple[str, int], list[tuple[str, int]]]: Selected dataset samples.\\n    \\\"\\\"\\\"\\n    if isinstance(index, slice):\\n        return [data_index[i] for i in range(*index.indices(len(data_index)))]\\n    elif isinstance(index, list):\\n        return [data_index[i] for i in index]\\n    else:\\n        raise ValueError(f\\\"Invalid index type {type(index)}.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/add_token.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/chunk_loss.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"927bce64a084ff7e91e138f20be18cbf12a09b9ace788528c2a1d75312bf4350\",\"content\":\"# Copyright 2026 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Chunked linear cross-entropy for SFT.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\n\\nimport torch\\nimport torch.nn as nn\\nimport torch.nn.functional as F\\nfrom torch import Tensor\\n\\nfrom ...utils.constants import IGNORE_INDEX\\nfrom ...utils.plugin import BasePlugin\\nfrom ...utils.types import BatchInput, HFModel, ModelOutput\\n\\n\\nclass LossPlugin(BasePlugin):\\n    def __call__(self, model: HFModel, chunk_size: int) -> ChunkLoss:\\n        return super().__call__(model, chunk_size)\\n\\n\\nclass _ChunkedLinearCrossEntropy(torch.autograd.Function):\\n    @staticmethod\\n    def forward(\\n        ctx,\\n        hidden_states: Tensor,\\n        head_weight: Tensor,\\n        head_bias: Tensor | None,\\n        labels: Tensor,\\n        loss_weights: Tensor,\\n        chunk_size: int,\\n    ) -> Tensor:\\n        needs_hidden_grad, needs_weight_grad, needs_bias_grad = ctx.needs_input_grad[:3]\\n        hidden_states_flat = hidden_states.reshape(-1, hidden_states.size(-1))\\n        labels_flat = labels.reshape(-1)\\n        loss_weights_flat = loss_weights.reshape(-1)\\n\\n        loss = torch.zeros((), device=hidden_states.device, dtype=torch.float32)\\n        grad_hidden = torch.empty_like(hidden_states_flat) if needs_hidden_grad else None\\n        # Avoid repeated BF16 rounding when summing head gradients across chunks.\\n        grad_weight = torch.zeros_like(head_weight, dtype=torch.float32) if needs_weight_grad else None\\n        grad_bias = (\\n            torch.zeros_like(head_bias, dtype=torch.float32) if head_bias is not None and needs_bias_grad else None\\n        )\\n\\n        for start in range(0, hidden_states_flat.size(0), chunk_size):\\n            end = start + chunk_size\\n            with torch.enable_grad():\\n                hidden_arg = hidden_states_flat[start:end].detach().requires_grad_(needs_hidden_grad)\\n                weight_arg = head_weight.detach().requires_grad_(needs_weight_grad)\\n                bias_arg = head_bias.detach().requires_grad_(needs_bias_grad) if head_bias is not None else None\\n                logits = F.linear(hidden_arg, weight_arg, bias_arg).float()\\n                token_loss = F.cross_entropy(\\n                    logits,\\n                    labels_flat[start:end],\\n                    reduction=\\\"none\\\",\\n                    ignore_index=IGNORE_INDEX,\\n                )\\n                chunk_loss = (token_loss * loss_weights_flat[start:end]).sum()\\n                grad_targets = [\\n                    tensor\\n                    for tensor, needed in (\\n                        (hidden_arg, needs_hidden_grad),\\n                        (weight_arg, needs_weight_grad),\\n                        (bias_arg, needs_bias_grad),\\n                    )\\n                    if tensor is not None and needed\\n                ]\\n                chunk_grads = torch.autograd.grad(chunk_loss, grad_targets) if grad_targets else ()\\n\\n            loss.add_(chunk_loss.detach())\\n            grad_index = 0\\n            if grad_hidden is not None:\\n                grad_hidden[start:end].copy_(chunk_grads[grad_index])\\n                grad_index += 1\\n            if grad_weight is not None:\\n                grad_weight.add_(chunk_grads[grad_index])\\n                grad_index += 1\\n            if grad_bias is not None:\\n                grad_bias.add_(chunk_grads[grad_index])\\n\\n        ctx.save_for_backward(\\n            grad_hidden.reshape_as(hidden_states) if grad_hidden is not None else None,\\n            grad_weight.to(head_weight.dtype) if grad_weight is not None else None,\\n            grad_bias.to(head_bias.dtype) if grad_bias is not None else None,\\n        )\\n        return loss\\n\\n    @staticmethod\\n    def backward(ctx, grad_output: Tensor):\\n        grad_hidden, grad_weight, grad_bias = ctx.saved_tensors\\n        return (\\n            grad_hidden * grad_output if grad_hidden is not None else None,\\n            grad_weight * grad_output if grad_weight is not None else None,\\n            grad_bias * grad_output if grad_bias is not None else None,\\n            None,\\n            None,\\n            None,\\n        )\\n\\n\\n@dataclass\\nclass _ChunkLossState:\\n    labels: Tensor\\n    loss_weights: Tensor\\n    loss: Tensor | None = None\\n    loss_version: int = 0\\n\\n\\n@LossPlugin(\\\"chunk_loss\\\").register()\\nclass ChunkLoss:\\n    \\\"\\\"\\\"Install Chunk Loss before distributed wrapping.\\n\\n    The model must call a plain Linear output head once and return its output\\n    directly as logits, without subsequent transformations. Other forwards keep\\n    their normal logits, including forwards of independently installed models.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, model: HFModel, chunk_size: int) -> None:\\n        self._output_head = model.get_output_embeddings()\\n        if type(self._output_head) is not nn.Linear:\\n            raise TypeError(\\\"Chunk Loss requires `get_output_embeddings()` to return a plain `torch.nn.Linear`.\\\")\\n\\n        self.chunk_size = chunk_size\\n        self._active_state: _ChunkLossState | None = None\\n        self._original_forward = self._output_head.forward\\n        self._output_head.forward = self._head_forward\\n        model.register_forward_hook(self._check_model_output)\\n\\n    def __call__(\\n        self,\\n        model: HFModel,\\n        model_inputs: dict[str, Tensor],\\n        labels: Tensor,\\n        loss_weights: Tensor,\\n    ) -> Tensor:\\n        \\\"\\\"\\\"Return a local weighted loss sum for already shifted targets.\\\"\\\"\\\"\\n        state = _ChunkLossState(labels=labels, loss_weights=loss_weights)\\n        self._active_state = state\\n        try:\\n            outputs: ModelOutput = model(**model_inputs)\\n        finally:\\n            self._active_state = None\\n\\n        if state.loss is None:\\n            raise RuntimeError(\\\"Chunk Loss did not reach the model output head.\\\")\\n        # Use the outer output so distributed wrappers retain their backward hooks.\\n        return outputs.logits\\n\\n    def compute_loss(\\n        self,\\n        model: HFModel,\\n        batch: BatchInput,\\n        *,\\n        device: torch.device,\\n        uses_mrope: bool,\\n    ) -> Tensor:\\n        \\\"\\\"\\\"Prepare an unsharded SFT batch and compute its weighted mean Chunk Loss.\\\"\\\"\\\"\\n        model_inputs = {\\n            key: value.to(device, non_blocking=True) for key, value in batch.items() if isinstance(value, torch.Tensor)\\n        }\\n        labels = model_inputs.pop(\\\"labels\\\")\\n        loss_weights = model_inputs.pop(\\\"loss_weights\\\")\\n        if uses_mrope:\\n            model_inputs.pop(\\\"position_ids\\\", None)\\n\\n        # Align each hidden state with its next-token target, as in the CP batch preparation.\\n        labels = F.pad(labels[..., 1:].contiguous(), (0, 1), value=IGNORE_INDEX)\\n        loss_weights = F.pad(loss_weights[..., 1:], (0, 1), value=0.0)\\n        numerator = self(model, model_inputs, labels, loss_weights)\\n        return numerator / (loss_weights.sum() + 1e-6)\\n\\n    def _head_forward(self, hidden_states: Tensor) -> Tensor:\\n        state = self._active_state\\n        if state is None:\\n            return self._original_forward(hidden_states)\\n        if state.loss is not None:\\n            raise RuntimeError(\\\"Chunk Loss expects one output-head call per model forward.\\\")\\n        if hidden_states.shape[:-1] != state.labels.shape or state.labels.shape != state.loss_weights.shape:\\n            raise ValueError(\\n                \\\"Chunk Loss hidden states, labels, and loss weights must share the same token layout: \\\"\\n                f\\\"hidden_states={tuple(hidden_states.shape)}, labels={tuple(state.labels.shape)}, \\\"\\n                f\\\"loss_weights={tuple(state.loss_weights.shape)}.\\\"\\n            )\\n\\n        state.loss = _ChunkedLinearCrossEntropy.apply(\\n            hidden_states,\\n            self._output_head.weight,\\n            self._output_head.bias,\\n            state.labels,\\n            state.loss_weights,\\n            self.chunk_size,\\n        )\\n        state.loss_version = state.loss._version\\n        return state.loss\\n\\n    def _check_model_output(self, _model, _args, outputs: ModelOutput) -> None:\\n        state = self._active_state\\n        if state is None or state.loss is None:\\n            return\\n        # Validate before DDP and other wrappers can replace the output tensor.\\n        # The version counter also catches in-place logits transformations.\\n        if outputs.logits is not state.loss or state.loss._version != state.loss_version:\\n            raise NotImplementedError(\\\"Chunk Loss does not support transformations after the model output head.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/deepspeed_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b5a2c487caf9aa6499dbc265b95f5332bc0230f6ddcff48ffa47377ce6314d10\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nfrom copy import deepcopy\\nfrom functools import lru_cache\\nfrom typing import Any\\n\\n\\n_registered_dist_config: Any | None = None\\n\\n\\ndef register_deepspeed_dist_config(dist_config: Any | None) -> None:\\n    \\\"\\\"\\\"Register backend config before model loading without involving the accelerator.\\\"\\\"\\\"\\n    global _registered_dist_config\\n    _registered_dist_config = dist_config\\n    is_deepspeed_zero3_enabled.cache_clear()\\n\\n\\n@lru_cache(maxsize=1)\\ndef is_deepspeed_zero3_enabled() -> bool:\\n    dist_config = _registered_dist_config\\n    if dist_config is None or getattr(dist_config, \\\"name\\\", None) != \\\"deepspeed\\\":\\n        return False\\n\\n    config_file = dist_config.get(\\\"config_file\\\")\\n    if not config_file:\\n        return False\\n    return _load_deepspeed_config(config_file).get(\\\"zero_optimization\\\", {}).get(\\\"stage\\\") == 3\\n\\n\\ndef _normalize_precision_enabled(value: Any) -> bool | str:\\n    if isinstance(value, str):\\n        value_lower = value.lower()\\n        if value_lower == \\\"true\\\":\\n            return True\\n        if value_lower == \\\"false\\\":\\n            return False\\n        if value_lower == \\\"auto\\\":\\n            return \\\"auto\\\"\\n    return value\\n\\n\\ndef infer_deepspeed_mixed_precision(ds_config: dict[str, Any]) -> str:\\n    ds_config.setdefault(\\\"fp16\\\", {})\\n    ds_config.setdefault(\\\"bf16\\\", {})\\n\\n    fp16_enabled = _normalize_precision_enabled(ds_config[\\\"fp16\\\"].get(\\\"enabled\\\", \\\"auto\\\"))\\n    bf16_enabled = _normalize_precision_enabled(ds_config[\\\"bf16\\\"].get(\\\"enabled\\\", \\\"auto\\\"))\\n\\n    # This project only supports DeepSpeed bf16 or no mixed precision.\\n    if fp16_enabled is True:\\n        raise ValueError(\\\"DeepSpeed only supports bf16 mixed precision for now, fp16 is not supported.\\\")\\n\\n    if bf16_enabled is True:\\n        mixed_precision = \\\"bf16\\\"\\n    elif bf16_enabled is False:\\n        mixed_precision = \\\"no\\\"\\n    elif fp16_enabled is False:\\n        mixed_precision = \\\"no\\\"\\n    else:\\n        # When both bf16/fp16 are left as auto (or absent), default to bf16.\\n        mixed_precision = \\\"bf16\\\"\\n\\n    ds_config[\\\"fp16\\\"][\\\"enabled\\\"] = False\\n    ds_config[\\\"bf16\\\"][\\\"enabled\\\"] = mixed_precision == \\\"bf16\\\"\\n    return mixed_precision\\n\\n\\ndef _unset_hf_deepspeed_config() -> None:\\n    try:\\n        from transformers.integrations import unset_hf_deepspeed_config\\n    except ImportError:\\n        from transformers.deepspeed import unset_hf_deepspeed_config\\n\\n    unset_hf_deepspeed_config()\\n\\n\\ndef _load_deepspeed_config(config_file: str) -> dict[str, Any]:\\n    with open(config_file, encoding=\\\"utf-8\\\") as f:\\n        return json.load(f)\\n\\n\\ndef setup_deepspeed_zero3_model_loading():\\n    \\\"\\\"\\\"Enable ZeRO-3-aware model loading for the registered backend config.\\\"\\\"\\\"\\n    dist_config = _registered_dist_config\\n    config_file = dist_config.get(\\\"config_file\\\") if dist_config is not None else None\\n    if not config_file:\\n        raise ValueError(\\\"DeepSpeed config_file is required in dist_config\\\")\\n\\n    from accelerate.utils import DeepSpeedPlugin\\n\\n    try:\\n        from transformers.integrations import is_deepspeed_zero3_enabled as _hf_is_deepspeed_zero3_enabled\\n    except ImportError:\\n        from transformers.deepspeed import is_deepspeed_zero3_enabled as _hf_is_deepspeed_zero3_enabled\\n\\n    # DeepSpeed configs often use \\\"auto\\\" placeholders that only make sense once\\n    # we know the current runtime batch settings and precision mode.\\n    ds_config = deepcopy(_load_deepspeed_config(config_file))\\n    if \\\"gradient_accumulation_steps\\\" not in ds_config or ds_config[\\\"gradient_accumulation_steps\\\"] == \\\"auto\\\":\\n        ds_config[\\\"gradient_accumulation_steps\\\"] = 1\\n    if \\\"train_micro_batch_size_per_gpu\\\" not in ds_config or ds_config[\\\"train_micro_batch_size_per_gpu\\\"] == \\\"auto\\\":\\n        ds_config[\\\"train_micro_batch_size_per_gpu\\\"] = 1\\n    if ds_config.get(\\\"train_batch_size\\\") == \\\"auto\\\":\\n        ds_config.pop(\\\"train_batch_size\\\")\\n\\n    zero_stage = ds_config.get(\\\"zero_optimization\\\", {}).get(\\\"stage\\\")\\n    if zero_stage != 3:\\n        return None\\n\\n    # ZeRO-3 model loading needs concrete fp16/bf16 flags, not \\\"auto\\\".\\n    mixed_precision = infer_deepspeed_mixed_precision(ds_config)\\n\\n    plugin = DeepSpeedPlugin(hf_ds_config=ds_config, zero3_init_flag=True)\\n\\n    if not plugin.hf_ds_config.is_zero3():\\n        return None\\n\\n    # Reuse the same precision inference rule as the training-time DeepSpeed path\\n    # so both model-loading and engine setup stay aligned.\\n    plugin.set_mixed_precision(mixed_precision)\\n    plugin.set_deepspeed_weakref()\\n\\n    if not _hf_is_deepspeed_zero3_enabled():\\n        raise RuntimeError(\\n            \\\"DeepSpeed ZeRO-3 model-loading bootstrap failed: transformers still reports zero3 disabled \\\"\\n            \\\"after constructing HfDeepSpeedConfig. This usually means the runtime is using a different transformers \\\"\\n            \\\"installation than expected, or the DeepSpeed global state was not established correctly.\\\"\\n        )\\n    return plugin\\n\\n\\ndef teardown_deepspeed_zero3_model_loading(plugin) -> None:\\n    if plugin is not None:\\n        _unset_hf_deepspeed_config()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/initialization.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ea42fdaa298caa05d38f23cffc865c72ec0eca1cd283a85e99910a69b76fc25\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nimport torch\\n\\nfrom ...accelerator.helper import DeviceType\\nfrom ...accelerator.interface import DistributedInterface\\nfrom ...utils.plugin import BasePlugin\\n\\n\\nclass InitPlugin(BasePlugin):\\n    def __call__(self) -> torch.device:\\n        return super().__call__()\\n\\n\\n@InitPlugin(\\\"init_on_meta\\\").register()\\ndef init_on_meta() -> torch.device:\\n    return torch.device(DeviceType.META.value)\\n\\n\\n@InitPlugin(\\\"init_on_rank0\\\").register()\\ndef init_on_rank0() -> torch.device:\\n    if DistributedInterface().get_rank() == 0:\\n        return torch.device(DeviceType.CPU.value)\\n    else:\\n        return torch.device(DeviceType.META.value)\\n\\n\\n@InitPlugin(\\\"init_on_default\\\").register()\\ndef init_on_default() -> torch.device:\\n    return DistributedInterface().current_device\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/base.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e9fb9876d49c18888f019d4219d56dc0ad405553c79573cfc2243149c546869d\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom abc import ABC, abstractmethod\\n\\nfrom ....utils.plugin import BasePlugin, ensure_methods_implemented\\nfrom ....utils.types import HFModel\\n\\n\\nclass KernelPlugin(BasePlugin):\\n    \\\"\\\"\\\"Plugin family for model kernel optimization classes.\\\"\\\"\\\"\\n\\n\\nclass BaseKernel(ABC):\\n    \\\"\\\"\\\"Template base for concrete kernel implementations.\\\"\\\"\\\"\\n\\n    def __init_subclass__(cls, **kwargs) -> None:\\n        super().__init_subclass__(**kwargs)\\n        ensure_methods_implemented(cls)\\n\\n    @staticmethod\\n    @abstractmethod\\n    def check_device() -> None: ...\\n\\n    @staticmethod\\n    def check_deps() -> None:\\n        pass\\n\\n    @classmethod\\n    def apply(cls, **kwargs) -> HFModel:\\n        cls.check_device()\\n        cls.check_deps()\\n        if kwargs.get(\\\"model\\\") is None:\\n            raise ValueError(f\\\"HFModel instance is required for {cls.__name__}.\\\")\\n\\n        return cls._apply(**kwargs)\\n\\n    @staticmethod\\n    @abstractmethod\\n    def _apply(**kwargs) -> HFModel: ...\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/interface.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d3f3eed5fc9b57a7a022d991a0918bb10a59ef15cd4d5e3d96bb98568dbed15b\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import Any\\n\\nfrom ....accelerator.helper import DeviceType, get_current_accelerator\\nfrom ....utils.types import HFModel\\nfrom .base import KernelPlugin\\n\\n# Import built-in implementations so their class decorators populate the registry.\\nfrom .liger_kernel_ops import LigerKernel  # noqa: F401\\nfrom .ops.linear_attention.fla import FlashLinearAttentionKernel  # noqa: F401\\nfrom .ops.mlp.cuda_fused_moe import CudaFusedMoEKernel  # noqa: F401\\nfrom .ops.mlp.npu_fused_moe import NpuFusedMoEKernel  # noqa: F401\\nfrom .ops.mlp.npu_swiglu import NpuSwiGluKernel  # noqa: F401\\nfrom .ops.rms_norm.npu_rms_norm import NpuRMSNormKernel  # noqa: F401\\nfrom .ops.rope.npu_rope import NpuRoPEKernel  # noqa: F401\\n\\n\\n_AUTO_KERNELS = {\\n    DeviceType.NPU: (\\\"npu_fused_moe\\\", \\\"npu_fused_rmsnorm\\\", \\\"npu_fused_rope\\\", \\\"npu_fused_swiglu\\\"),\\n}\\n\\n\\ndef _apply_auto_kernels(model: HFModel, **kwargs) -> HFModel:\\n    device_type = get_current_accelerator().type\\n    for kernel_name in _AUTO_KERNELS.get(device_type, ()):\\n        model = KernelPlugin(kernel_name).apply(model=model, **kwargs)\\n\\n    return model\\n\\n\\ndef apply_kernels(model: HFModel, config: dict[str, Any], require_logits: bool = False) -> HFModel:\\n    \\\"\\\"\\\"Apply the comma-separated kernel names selected by ``kernel_config.name``.\\\"\\\"\\\"\\n    kernel_names = config.get(\\\"name\\\")\\n    if not isinstance(kernel_names, str):\\n        raise TypeError(\\\"kernel_config.name must be a string.\\\")\\n\\n    names = [name.strip() for name in kernel_names.split(\\\",\\\") if name.strip()]\\n    if not names:\\n        raise ValueError(\\\"kernel_config.name must contain at least one kernel name.\\\")\\n\\n    for name in names:\\n        if name == \\\"auto\\\":\\n            model = _apply_auto_kernels(model=model, config=config, require_logits=require_logits)\\n        else:\\n            model = KernelPlugin(name).apply(model=model, config=config, require_logits=require_logits)\\n\\n    return model\\n\\n\\ndef apply_v1_kernels(model: HFModel, use_v1_kernels: bool) -> HFModel:\\n    \\\"\\\"\\\"Apply v1 automatic kernels for the transitional v0 ``use_v1_kernels`` option.\\\"\\\"\\\"\\n    if not use_v1_kernels:\\n        return model\\n\\n    return apply_kernels(model, {\\\"name\\\": \\\"auto\\\"})\\n\\n\\ndef apply_kernel(kernel_id: str, **kwargs) -> HFModel:\\n    if kernel_id == \\\"auto\\\":\\n        return _apply_auto_kernels(**kwargs)\\n\\n    return KernelPlugin(kernel_id).apply(**kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/liger_kernel_ops.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"49208b53731ce4352d4bbde2b81acc99c5ee441f5d432df12ccb546d567b4bb6\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"The definition of Liger Kernel.\\n\\nInit Phase:\\n1. Define LigerKernel class.\\n2. Register Liger kernel.\\n\\n\\\"\\\"\\\"\\n\\nimport inspect\\n\\nfrom ....accelerator.helper import DeviceType, get_current_accelerator\\nfrom ....utils.logging import get_logger\\nfrom ....utils.types import HFModel\\nfrom .base import BaseKernel, KernelPlugin\\n\\n\\nlogger = get_logger(__name__)\\n\\n_LIGER_FN_BY_MODEL_TYPE: dict[str, str] = {\\n    \\\"qwen3\\\": \\\"apply_liger_kernel_to_qwen3\\\",\\n    \\\"qwen3_moe\\\": \\\"apply_liger_kernel_to_qwen3_moe\\\",\\n    \\\"qwen3_next\\\": \\\"apply_liger_kernel_to_qwen3_next\\\",\\n    \\\"qwen3_5\\\": \\\"apply_liger_kernel_to_qwen3_5\\\",\\n    \\\"qwen3_5_text\\\": \\\"apply_liger_kernel_to_qwen3_5_text\\\",\\n    \\\"qwen3_5_moe\\\": \\\"apply_liger_kernel_to_qwen3_5_moe\\\",\\n    \\\"qwen3_5_moe_text\\\": \\\"apply_liger_kernel_to_qwen3_5_moe_text\\\",\\n}\\n\\n\\n@KernelPlugin(\\\"liger_kernel\\\").register()\\nclass LigerKernel(BaseKernel):\\n    \\\"\\\"\\\"Liger Kernel for optimized model training.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def check_device() -> None:\\n        current = get_current_accelerator().type\\n        if current not in (DeviceType.CUDA, DeviceType.NPU):\\n            raise RuntimeError(f\\\"LigerKernel requires CUDA or NPU, current accelerator is {current}.\\\")\\n\\n    @staticmethod\\n    def check_deps() -> None:\\n        \\\"\\\"\\\"Checks if the required dependencies for the kernel are available.\\\"\\\"\\\"\\n        try:\\n            import liger_kernel  # noqa: F401\\n        except ImportError:\\n            raise RuntimeError(\\\"Liger kernel is not installed.\\\") from None\\n\\n    @staticmethod\\n    def _apply(**kwargs) -> \\\"HFModel\\\":\\n        \\\"\\\"\\\"Applies the Liger kernel to the model.\\n\\n        Args:\\n            **kwargs: Must include ``model``. Optional ``use_kernels`` is a list of Liger op\\n                names to enable exclusively, or the string ``\\\"auto\\\"`` to use each\\n                ``apply_liger_kernel_to_*`` function's signature defaults (same as calling\\n                upstream with only ``model``). Optional ``require_logits`` forces non-fused\\n                cross entropy when supported.\\n\\n        Returns:\\n            HFModel: The model with Liger kernel applied.\\n\\n        Raises:\\n            ValueError: If the model is not provided.\\n            RuntimeError: If dependencies are not met.\\n        \\\"\\\"\\\"\\n        model = kwargs.get(\\\"model\\\")\\n        config = kwargs.get(\\\"config\\\")\\n        use_kernels = kwargs.get(\\\"use_kernels\\\", \\\"auto\\\")\\n\\n        require_logits = kwargs.get(\\\"require_logits\\\", False)\\n        if config is not None:\\n            require_logits = config.get(\\\"require_logits\\\", require_logits)\\n\\n        model_type = getattr(model.config, \\\"model_type\\\", None)\\n\\n        if model_type not in _LIGER_FN_BY_MODEL_TYPE:\\n            logger.warning_rank0(\\\"Current model does not support liger kernel.\\\")\\n            return model\\n\\n        import liger_kernel.transformers as liger_transformers\\n\\n        apply_liger_kernel = getattr(liger_transformers, _LIGER_FN_BY_MODEL_TYPE[model_type])\\n\\n        sig = inspect.signature(apply_liger_kernel).parameters\\n        togglable = [name for name in sig if name != \\\"model\\\"]\\n\\n        def _normalize_op_name(raw: str) -> str:\\n            key = raw.strip().lower().replace(\\\"-\\\", \\\"_\\\")\\n            aliases = {\\n                \\\"rmsnorm\\\": \\\"rms_norm\\\",\\n                \\\"flce\\\": \\\"fused_linear_cross_entropy\\\",\\n                \\\"lce\\\": \\\"fused_linear_cross_entropy\\\",\\n                \\\"fused_ce\\\": \\\"fused_linear_cross_entropy\\\",\\n            }\\n            return aliases.get(key, key)\\n\\n        if use_kernels is not None and len(use_kernels) == 0:\\n            return model\\n\\n        if use_kernels != \\\"auto\\\":\\n            selected = {_normalize_op_name(k) for k in use_kernels}\\n            ops = selected - set(togglable)\\n            if ops:\\n                raise ValueError(\\n                    f\\\"Unknown Liger op(s) {sorted(ops)} for model_type={model_type}. Valid: {sorted(togglable)}\\\"\\n                )\\n            if \\\"cross_entropy\\\" in selected and \\\"fused_linear_cross_entropy\\\" in selected:\\n                raise ValueError(\\\"cross_entropy and fused_linear_cross_entropy cannot both be enabled.\\\")\\n            call_kwargs = {name: (name in selected) for name in togglable}\\n            call_kwargs[\\\"model\\\"] = model\\n        else:\\n            # Mirror ``liger_kernel`` signature defaults so patches match upstream defaults\\n            # and logging reflects enabled ops (omitted kwargs only live in the callee).\\n            call_kwargs = {\\\"model\\\": model}\\n            for name in togglable:\\n                param = sig[name]\\n                if param.default is not inspect.Parameter.empty:\\n                    call_kwargs[name] = param.default\\n\\n        if require_logits and \\\"fused_linear_cross_entropy\\\" in sig:\\n            logger.warning_rank0(\\\"Current training stage does not support chunked cross entropy.\\\")\\n            call_kwargs[\\\"fused_linear_cross_entropy\\\"] = False\\n            call_kwargs[\\\"cross_entropy\\\"] = True\\n\\n        apply_liger_kernel(**call_kwargs)\\n\\n        applied = sorted(name for name, on in call_kwargs.items() if name != \\\"model\\\" and on)\\n        logger.info_rank0(f\\\"These Liger ops are applied to the model: {applied}\\\")\\n\\n        return model\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/ops/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/ops/linear_attention/fla.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1abe2fe50f27802a543af5a953d6af8d4fda6e4426c880e9b1a0c549342b030f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Flash Linear Attention kernel plugin backed by FSDPTurbo's operator registry.\\\"\\\"\\\"\\n\\nfrom functools import partial\\n\\nfrom ......accelerator.helper import DeviceType, get_current_accelerator\\nfrom ......utils import logging\\nfrom ......utils.types import HFModel\\nfrom ...base import BaseKernel, KernelPlugin\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\nCHUNK_GATED_DELTA_RULE = \\\"chunk_gated_delta_rule\\\"\\nFUSED_RECURRENT_GATED_DELTA_RULE = \\\"fused_recurrent_gated_delta_rule\\\"\\nFLASH_LINEAR_ATTENTION_KERNELS = (\\n    CHUNK_GATED_DELTA_RULE,\\n    FUSED_RECURRENT_GATED_DELTA_RULE,\\n)\\nFLA_MODULE_ATTRIBUTES = {\\n    CHUNK_GATED_DELTA_RULE: \\\"chunk_gated_delta_rule\\\",\\n    FUSED_RECURRENT_GATED_DELTA_RULE: \\\"recurrent_gated_delta_rule\\\",\\n}\\nSUPPORTED_CHUNK_SIZES = (16, 32, 64)\\n\\n\\n@KernelPlugin(\\\"flash-linear-attention\\\").register()\\nclass FlashLinearAttentionKernel(BaseKernel):\\n    \\\"\\\"\\\"Install selected FLA callables through FSDPTurbo's device operator registry.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def check_device() -> None:\\n        current = get_current_accelerator().type\\n        if current not in (DeviceType.CUDA, DeviceType.NPU):\\n            raise RuntimeError(f\\\"FlashLinearAttentionKernel requires CUDA or NPU, current accelerator is {current}.\\\")\\n\\n    @staticmethod\\n    def check_deps() -> None:\\n        try:\\n            import fla.ops.gated_delta_rule  # noqa: F401\\n            import fsdp_turbo.ops.fla  # noqa: F401\\n            from fsdp_turbo.ops.registry import get_op  # noqa: F401\\n            from fsdp_turbo.utils.patch import patch_model_members  # noqa: F401\\n        except ImportError as exc:\\n            raise RuntimeError(\\\"Flash Linear Attention and FSDPTurbo are required for this kernel.\\\") from exc\\n\\n    @staticmethod\\n    def _apply(**kwargs) -> HFModel:\\n        model = kwargs[\\\"model\\\"]\\n        config = kwargs.get(\\\"config\\\") or {}\\n        include_kernels = config.get(\\\"include_kernels\\\", \\\"auto\\\")\\n        chunk_size = config.get(\\\"chunk_size\\\", 64)\\n\\n        if include_kernels == \\\"auto\\\" or include_kernels is True:\\n            selected = list(FLASH_LINEAR_ATTENTION_KERNELS)\\n        elif isinstance(include_kernels, str):\\n            selected = [name.strip() for name in include_kernels.split(\\\",\\\") if name.strip()]\\n        else:\\n            raise TypeError(\\\"kernel_config.include_kernels must be 'auto' or a comma-separated string.\\\")\\n\\n        if not selected:\\n            raise ValueError(\\\"kernel_config.include_kernels must select at least one FLA kernel.\\\")\\n\\n        unsupported = set(selected).difference(FLASH_LINEAR_ATTENTION_KERNELS)\\n        if unsupported:\\n            raise ValueError(f\\\"Unsupported Flash Linear Attention kernels: {sorted(unsupported)}\\\")\\n        if isinstance(chunk_size, bool) or not isinstance(chunk_size, int) or chunk_size not in SUPPORTED_CHUNK_SIZES:\\n            raise ValueError(f\\\"chunk_size must be one of {SUPPORTED_CHUNK_SIZES}, got {chunk_size!r}.\\\")\\n\\n        from fsdp_turbo.ops.registry import get_op\\n        from fsdp_turbo.utils.patch import patch_model_members\\n\\n        patched = 0\\n        named_modules = tuple(model.named_modules())\\n        for op_name in selected:\\n            module_attribute = FLA_MODULE_ATTRIBUTES[op_name]\\n            op = get_op(op_name)\\n            configured_op = partial(op, chunk_size=chunk_size) if op_name == CHUNK_GATED_DELTA_RULE else op\\n            targets = {\\n                f\\\"{type(module).__module__}.{type(module).__name__}.{module_attribute}\\\"\\n                for _, module in named_modules\\n                if callable(getattr(module, module_attribute, None))\\n            }\\n            matched = patch_model_members(model, sorted(targets), configured_op) if targets else 0\\n            if matched == 0:\\n                raise RuntimeError(f\\\"FLA operator `{op_name}` did not match any model module attributes.\\\")\\n            patched += matched\\n\\n        logger.info_rank0(f\\\"Flash Linear Attention kernels updated {patched} module callables: {selected}.\\\")\\n        return model\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/ops/mlp/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/plugins/model_plugins/kernels/ops/mlp/cuda_fused_moe.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a82eb1ce14e69338f14f815336fbee5107d1e1a4fba53f4d72c85513289dd290\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Pure-Triton Fused MoE Kernel for NVIDIA GPUs.\\n\\nReplaces the HuggingFace per-expert Python loop with a fully fused Triton pipeline:\\n- Forward: scatter \u2192 grouped GEMM fc1 \u2192 SiLU\u00b7gate \u2192 apply routing \u2192 grouped GEMM fc2 \u2192 gather\\n- Backward: all dX via grouped GEMM, all dW via grouped GEMM (no Python loops)\\n\\nSupported models: Mixtral, Qwen3-MoE, Qwen3.5-MoE.\\n\\\"\\\"\\\"\\n\\nimport logging\\nimport types\\n\\nimport torch\\nimport torch.nn.functional as F\\n\\nfrom ......accelerator.helper import DeviceType, get_current_accelerator\\nfrom ......utils.types import HFModel\\nfrom ...base import BaseKernel, KernelPlugin\\n\\n\\ntry:\\n    from .triton_grouped_gemm import (\\n        group_gemm_same_mn,\\n        group_gemm_same_nk,\\n        moe_gather,\\n        moe_scatter,\\n    )\\nexcept ImportError as exc:\\n    _TRITON_IMPORT_ERROR = exc\\nelse:\\n    _TRITON_IMPORT_ERROR = None\\n\\n\\nlogger = logging.getLogger(__name__)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Autograd Function: Full Triton MoE forward + backward\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TritonFusedMoeFunction(torch.autograd.Function):\\n    \\\"\\\"\\\"Fused MoE expert computation using Triton grouped GEMMs.\\n\\n    Forward: scatter \u2192 fc1 (group GEMM) \u2192 SiLU\u00b7gate \u2192 weight \u2192 fc2 (group GEMM) \u2192 gather\\n    Backward: all gradients computed via grouped GEMMs in single kernel launches.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def forward(\\n        ctx,\\n        num_experts,\\n        gate_weights,\\n        expert_index,\\n        hidden_states,\\n        fc1_weight,\\n        fc2_weight,\\n    ):\\n        \\\"\\\"\\\"Forward pass.\\n\\n        Args:\\n            ctx: autograd context\\n            num_experts: int\\n            gate_weights: (num_tokens, top_k) routing weights\\n            expert_index: (num_tokens, top_k) expert assignments\\n            hidden_states: (num_tokens, hidden_dim)\\n            fc1_weight: (E, 2*inter, hidden) merged gate+up weight\\n            fc2_weight: (E, hidden, inter) down projection weight\\n        \\\"\\\"\\\"\\n        # Compute scatter index: maps (token, topk) \u2192 position in sorted buffer\\n        scatter_index = expert_index.flatten().argsort(stable=True).argsort().int().view(expert_index.shape)\\n\\n        # Token counts per expert and cumulative boundaries\\n        splits = torch.zeros(num_experts, dtype=torch.int32, device=hidden_states.device)\\n        flat_experts = expert_index.flatten().int()\\n        splits.scatter_add_(0, flat_experts.long(), torch.ones_like(flat_experts))\\n        cumsum_t = torch.cumsum(splits, dim=0)\\n\\n        # Scatter hidden states to sorted expert buffer\\n        scatter_output = moe_scatter(hidden_states, scatter_index)\\n\\n        # FC1: grouped GEMM (scatter_output @ fc1_weight.T)\\n        max_M = int(splits.max().item())\\n        fc1_output = group_gemm_same_nk(\\n            a=scatter_output,\\n            b=fc1_weight,\\n            cumsum_M=cumsum_t,\\n            max_M=max_M,\\n            transpose_b=True,\\n        )\\n\\n        # SiLU gate activation\\n        fc1_1_output, fc1_2_output = fc1_output.chunk(2, dim=-1)\\n        fc1_1_activation = torch.nn.functional.silu(fc1_1_output)\\n        fc1_activation = fc1_1_activation * fc1_2_output\\n\\n        # Apply routing weights before fc2 (mathematically equivalent to after)\\n        reshaped_gate_weight = gate_weights.reshape(-1, 1)\\n        scattered_gate_weight = torch.empty_like(reshaped_gate_weight)\\n        scattered_gate_weight[scatter_index.flatten().long()] = reshaped_gate_weight\\n        fc1_weighted_output = fc1_activation * scattered_gate_weight\\n\\n        # FC2: grouped GEMM (fc1_weighted @ fc2_weight.T)\\n        fc2_output = group_gemm_same_nk(\\n            a=fc1_weighted_output,\\n            b=fc2_weight,\\n            cumsum_M=cumsum_t,\\n            max_M=max_M,\\n            transpose_b=True,\\n        )\\n\\n        # Gather back to original token positions (sum over topk)\\n        expert_output = moe_gather(fc2_output, scatter_index)\\n\\n        ctx.num_experts = num_experts\\n        ctx.save_for_backward(\\n            gate_weights,\\n            fc1_weight,\\n            fc2_weight,\\n            hidden_states,\\n            scatter_index,\\n            scatter_output,\\n            cumsum_t,\\n            fc1_1_output,\\n            fc1_2_output,\\n            fc1_activation,\\n            scattered_gate_weight,\\n            fc1_weighted_output,\\n        )\\n\\n        return expert_output\\n\\n    @staticmethod\\n    def backward(ctx, grad_output):\\n        (\\n            gate_weights,\\n            fc1_weight,\\n            fc2_weight,\\n            hidden_states,\\n            scatter_index,\\n            scatter_output,\\n            cumsum_t,\\n            fc1_1_output,\\n            fc1_2_output,\\n            fc1_activation,\\n            scattered_gate_weight,\\n            fc1_weighted_output,\\n        ) = ctx.saved_tensors\\n        num_experts = ctx.num_experts\\n        hidden_dim = grad_output.shape[-1]\\n        grad_output = grad_output.reshape(-1, hidden_dim).contiguous()\\n\\n        # Recompute max_M from cumsum\\n        splits = torch.zeros(num_experts, dtype=cumsum_t.dtype, device=cumsum_t.device)\\n        splits[0] = cumsum_t[0]\\n        splits[1:] = cumsum_t[1:] - cumsum_t[:-1]\\n        max_M = int(splits.max().item())\\n\\n        # Step 1: Scatter grad_output to expert buffer\\n        grad_fc2_output = moe_scatter(grad_output, scatter_index)\\n\\n        # Step 2: FC2 backward\\n        # dX for fc2: grad_fc2_output @ fc2_weight (transpose_b=False since fc2 is (E, hidden, inter))\\n        grad_fc1_weighted_output = group_gemm_same_nk(\\n            a=grad_fc2_output,\\n            b=fc2_weight,\\n            cumsum_M=cumsum_t,\\n            max_M=max_M,\\n            transpose_b=False,\\n        )\\n\\n        # dW for fc2: grad_fc2_output.T @ fc1_weighted_output\\n        grad_fc2_weight = None\\n        if fc2_weight.requires_grad:\\n            grad_fc2_weight = torch.empty_like(fc2_weight)\\n            group_gemm_same_mn(\\n                a=grad_fc2_output,\\n                b=fc1_weighted_output,\\n                c=grad_fc2_weight,\\n                cumsum_K=cumsum_t,\\n            )\\n\\n        # Step 3: Routing weight backward\\n        grad_fc1_activation = grad_fc1_weighted_output * scattered_gate_weight\\n        grad_scattered_gate_weight = torch.sum(fc1_activation * grad_fc1_weighted_output, dim=-1)\\n        grad_gate_weight = grad_scattered_gate_weight[scatter_index.flatten().long()]\\n        grad_gate_weight = grad_gate_weight.reshape(gate_weights.shape)\\n\\n        # Recompute silu activation for backward\\n        fc1_1_activation = torch.nn.functional.silu(fc1_1_output)\\n\\n        # Step 4: SiLU gate backward\\n        grad_fc1_1_activation = grad_fc1_activation * fc1_2_output\\n        grad_fc1_2_output = fc1_1_activation * grad_fc1_activation\\n\\n        # SiLU backward: d/dx[x * sigmoid(x)] = sigmoid(x) + x * sigmoid(x) * (1 - sigmoid(x))\\n        grad_fc1_1_output = torch.ops.aten.silu_backward(grad_fc1_1_activation, fc1_1_output)\\n\\n        # Merge fc1 gradients back to (total_M, 2*inter)\\n        grad_fc1_output = torch.cat([grad_fc1_1_output, grad_fc1_2_output], dim=-1)\\n\\n        # Step 5: FC1 backward\\n        # dX for fc1: grad_fc1_output @ fc1_weight (transpose_b=False)\\n        grad_scatter_output = group_gemm_same_nk(\\n            a=grad_fc1_output,\\n            b=fc1_weight,\\n            cumsum_M=cumsum_t,\\n            max_M=max_M,\\n            transpose_b=False,\\n        )\\n\\n        # dW for fc1: grad_fc1_output.T @ scatter_output\\n        grad_fc1_weight = None\\n        if fc1_weight.requires_grad:\\n            grad_fc1_weight = torch.empty_like(fc1_weight)\\n            group_gemm_same_mn(\\n                a=grad_fc1_output,\\n                b=scatter_output,\\n                c=grad_fc1_weight,\\n                cumsum_K=cumsum_t,\\n            )\\n\\n        # Step 6: Gather gradients back to original positions\\n        grad_hidden_states = moe_gather(grad_scatter_output, scatter_index)\\n        grad_hidden_states = grad_hidden_states.reshape(hidden_states.shape)\\n\\n        return (\\n            None,  # num_experts\\n            grad_gate_weight,  # gate_weights\\n            None,  # expert_index\\n            grad_hidden_states,  # hidden_states\\n            grad_fc1_weight,  # fc1_weight\\n            grad_fc2_weight,  # fc2_weight\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Patched forward functions\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _triton_moe_experts_forward(\\n    self,\\n    hidden_states: torch.Tensor,\\n    top_k_index: torch.Tensor,\\n    top_k_weights: torch.Tensor,\\n) -> torch.Tensor:\\n    \\\"\\\"\\\"Replacement forward for v5+ MoE expert modules with stacked 3D weights.\\\"\\\"\\\"\\n    return TritonFusedMoeFunction.apply(\\n        self.num_experts,\\n        top_k_weights.to(hidden_states.dtype),\\n        top_k_index,\\n        hidden_states,\\n        self.gate_up_proj,\\n        self.down_proj,\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Legacy (transformers < 5.0) support: weight stacking + SparseMoeBlock patch\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _StackedExpertWeights(torch.nn.Module):\\n    \\\"\\\"\\\"Lightweight container holding stacked 3D expert weight tensors.\\\"\\\"\\\"\\n\\n    def __init__(self, gate_up_proj: torch.Tensor, down_proj: torch.Tensor, num_experts: int):\\n        super().__init__()\\n        self.gate_up_proj = torch.nn.Parameter(gate_up_proj)\\n        self.down_proj = torch.nn.Parameter(down_proj)\\n        self.num_experts = num_experts\\n\\n\\ndef _stack_expert_weights(module: torch.nn.Module) -> None:\\n    \\\"\\\"\\\"Replace nn.ModuleList of individual experts with stacked 3D parameter tensors.\\\"\\\"\\\"\\n    experts = module.experts\\n    num_experts = len(experts)\\n\\n    gate_up_list = []\\n    for expert in experts:\\n        gate_w = expert.gate_proj.weight.data  # (inter, hidden)\\n        up_w = expert.up_proj.weight.data  # (inter, hidden)\\n        gate_up_list.append(torch.cat([gate_w, up_w], dim=0))  # (2*inter, hidden)\\n    gate_up_proj = torch.stack(gate_up_list, dim=0)  # (E, 2*inter, hidden)\\n\\n    down_proj = torch.stack([e.down_proj.weight.data for e in experts], dim=0)  # (E, hidden, inter)\\n\\n    module.experts = _StackedExpertWeights(gate_up_proj, down_proj, num_experts)\\n    logger.info(\\n        f\\\"cuda_fused_moe: Stacked {num_experts} expert weights into \\\"\\n        f\\\"gate_up_proj {tuple(gate_up_proj.shape)}, down_proj {tuple(down_proj.shape)}\\\"\\n    )\\n\\n\\ndef _triton_moe_sparse_block_forward(self, hidden_states: torch.Tensor):\\n    \\\"\\\"\\\"Replacement forward for legacy SparseMoeBlock with inline routing.\\\"\\\"\\\"\\n    batch_size, sequence_length, hidden_dim = hidden_states.shape\\n    hidden_states = hidden_states.view(-1, hidden_dim)\\n\\n    router_logits = self.gate(hidden_states)\\n    routing_weights = F.softmax(router_logits, dim=1, dtype=torch.float)\\n    routing_weights, selected_experts = torch.topk(routing_weights, self.top_k, dim=-1)\\n    if self.norm_topk_prob:\\n        routing_weights /= routing_weights.sum(dim=-1, keepdim=True)\\n    routing_weights = routing_weights.to(hidden_states.dtype)\\n\\n    final_hidden_states = TritonFusedMoeFunction.apply(\\n        self.num_experts,\\n        routing_weights,\\n        selected_experts,\\n        hidden_states,\\n        self.experts.gate_up_proj,\\n        self.experts.down_proj,\\n    )\\n\\n    final_hidden_states = final_hidden_states.reshape(batch_size, sequence_length, hidden_dim)\\n    return final_hidden_states, router_logits\\n\\n\\n# ---------------------------------------------------------------------------\\n# Module mapping\\n# ---------------------------------------------------------------------------\\n\\n_TRITON_MOE_MAPPING: dict[str, dict[str, object]] = {\\n    \\\"MixtralForCausalLM\\\": {\\n        \\\"MixtralExperts\\\": _triton_moe_experts_forward,\\n    },\\n    \\\"Qwen3MoeForCausalLM\\\": {\\n        \\\"Qwen3MoeExperts\\\": _triton_moe_experts_forward,\\n        \\\"Qwen3MoeSparseMoeBlock\\\": _triton_moe_sparse_block_forward,\\n    },\\n    \\\"Qwen3_5MoeForCausalLM\\\": {\\n        \\\"Qwen3_5MoeExperts\\\": _triton_moe_experts_forward,\\n    },\\n    \\\"Qwen3_5MoeForConditionalGeneration\\\": {\\n        \\\"Qwen3_5MoeExperts\\\": _triton_moe_experts_forward,\\n    },\\n}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Kernel registration\\n# ---------------------------------------------------------------------------\\n\\n\\n@KernelPlugin(\\\"cuda_fused_moe\\\").register()\\nclass CudaFusedMoEKernel(BaseKernel):\\n    \\\"\\\"\\\"Pure-Triton fused MoE kernel for NVIDIA CUDA GPUs.\\n\\n    Replaces HuggingFace per-expert Python loops with a fully fused Triton pipeline:\\n    - Forward: scatter + grouped GEMMs + gather (single kernel per GEMM)\\n    - Backward: all dX and dW via grouped GEMMs (no Python loops)\\n\\n    Requires: CUDA GPU + Triton\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def check_device() -> None:\\n        current = get_current_accelerator().type\\n        if current != DeviceType.CUDA:\\n            raise RuntimeError(f\\\"CudaFusedMoEKernel requires CUDA, current accelerator is {current}.\\\")\\n\\n    @staticmethod\\n    def check_deps() -> None:\\n        if _TRITON_IMPORT_ERROR is not None:\\n            raise RuntimeError(\\\"cuda_fused_moe requires Triton.\\\") from _TRITON_IMPORT_ERROR\\n\\n    @staticmethod\\n    def _apply(**kwargs) -> HFModel:\\n        model = kwargs.get(\\\"model\\\")\\n\\n        archs = getattr(model.config, \\\"architectures\\\", None) or []\\n        target_mapping = None\\n        for arch in archs:\\n            if arch in _TRITON_MOE_MAPPING:\\n                target_mapping = _TRITON_MOE_MAPPING[arch]\\n                break\\n\\n        if target_mapping is None:\\n            logger.info(\\n                f\\\"cuda_fused_moe: Model architecture {archs} not supported. \\\"\\n                f\\\"Supported: {list(_TRITON_MOE_MAPPING.keys())}\\\"\\n            )\\n            return model\\n\\n        patched_count = 0\\n        for module in model.modules():\\n            class_name = module.__class__.__name__\\n            if class_name not in target_mapping:\\n                continue\\n\\n            target_fn = target_mapping[class_name]\\n\\n            if hasattr(module, \\\"gate_up_proj\\\") and hasattr(module, \\\"down_proj\\\"):\\n                module.forward = types.MethodType(target_fn, module)\\n                patched_count += 1\\n            elif (\\n                hasattr(module, \\\"experts\\\")\\n                and isinstance(module.experts, torch.nn.ModuleList)\\n                and hasattr(module, \\\"gate\\\")\\n            ):\\n                _stack_expert_weights(module)\\n                module.forward = types.MethodType(target_fn, module)\\n                patched_count += 1\\n\\n        if patched_count > 0:\\n            logger.info(f\\\"cuda_fused_moe: Patched {patched_count} MoE expert modules with pure Triton pipeline.\\\")\\n        else:\\n            logger.warning(\\\"cuda_fused_moe: No MoE expert modules found to patch.\\\")\\n\\n        return model\\n\"}]}";
